                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "They automatically encrypt the database connection.", "They run the query in a secure sandbox isolated from the database.", "They strip all single quotes (`'`) from user input before execution.", "They separate the SQL logic from the data, sending the query structure and the parameters separately, preventing malicious input from altering the query structure." },
                    3, "Prepared statements send the SQL structure and data payload in two distinct steps. The database engine treats parameters strictly as data, never as executable code. Assuming they just strip quotes is a dangerous misconception; they fundamentally neutralize SQL injection.",
                    skillId: 7),
                CreateQuestion(id++, "What is a Closure in PHP?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Backend,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "An anonymous function that can capture and inherit variables from the parent scope using the `use` keyword.", "A design pattern used to secure sensitive configuration files.", "A built-in class used to permanently close database connections.", "A specific type of loop that always guarantees termination." },
                    0, "A closure is an anonymous function capable of capturing scope via the `use` keyword. This is vital for modern PHP callbacks and array mapping functions. Confusing it with database closures completely misses its functional programming utility.",
                    skillId: 7),
                CreateQuestion(id++, "What happens if you declare `strict_types=1` at the top of a PHP file?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Backend,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "It disables all dynamic variables and forces the developer to define variables using C-style types.", "It prevents the usage of arrays and objects, allowing only scalar types.", "It globally forces all PHP files in the project to use strict typing.", "It forces PHP to enforce exact type matching for function arguments and return types within that specific file, throwing a TypeError if they mismatch." },
                    3, "Declaring `strict_types=1` enforces strict type safety within that file, preventing PHP's default type coercion. It does not apply globally. Utilizing it prevents hidden bugs and ensures the codebase behaves predictably, acting as a hallmark of high-quality modern PHP.",
                    skillId: 7),
                CreateQuestion(id++, "What is 'Late Static Binding' in PHP and how is it used?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Backend,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "It allows a static method inherited from a parent class to reference the child class that called it, using the `static::` keyword instead of `self::`.", "It allows developers to change a constant's value at runtime.", "It delays the loading of static assets (like CSS and JS) until the PHP script finishes executing.", "It binds a variable to memory strictly at compile time." },
                    0, "`static::` evaluates to the class that was actually called at runtime, whereas `self::` always evaluates to the class where the method was defined. Confusing them breaks polymorphism in inherited static methods. Understanding late static binding is crucial for robust factory patterns.",
                    skillId: 7),
                CreateQuestion(id++, "What does PSR-4 define in the PHP ecosystem?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Backend,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "A standard API for connecting to NoSQL databases.", "A standard security protocol for hashing passwords.", "A standard for autoloading classes from file paths, mapping fully qualified namespaces to specific directory structures.", "A standard formatting rule for indentations and brackets." },
                    2, "PSR-4 maps PHP namespaces directly to directory structures, allowing Composer to dynamically autoload classes without manual `require` statements. Confusing it with formatting rules ignores its architectural impact. It is the absolute foundation of modern PHP frameworks.",
                    skillId: 7),
                CreateQuestion(id++, "What does the `yield` keyword do inside a PHP function?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Backend,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "It throws a highly specific custom Exception that cannot be caught.", "It imports a file directly into the memory heap.", "It forcefully stops a running thread and yields CPU time to Apache.", "It turns the function into a Generator, allowing it to pause execution, return a value, and resume later, which is highly memory-efficient for large datasets." },
                    3, "`yield` turns a function into a Generator, producing values lazily one at a time instead of holding a massive array in memory. Assuming it yields CPU time (like in OS threads) misses its memory-management role. Generators prevent Out-Of-Memory errors when parsing massive files.",
                    skillId: 7),
                CreateQuestion(id++, "What is the primary advantage of the `match` expression (introduced in PHP 8) over the traditional `switch` statement?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Backend,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "`switch` was completely removed in PHP 8, making `match` the only option.", "`match` is asynchronous and can handle multiple cases in parallel.", "`match` allows you to evaluate regular expressions directly as the condition.", "`match` performs strict type comparisons (`===`), returns a value natively, and does not require `break` statements to prevent fall-through." },
                    3, "The `match` expression strictly compares types and automatically returns a value without needing `break` statements, eliminating 'fall-through' bugs common in `switch`. Assuming `switch` was removed is false. `match` drastically simplifies conditional logic.",
                    skillId: 7),
                CreateQuestion(id++, "What is the purpose of a Dependency Injection (DI) Container in modern PHP frameworks (like Laravel or Symfony)?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Backend,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "It injects CSS and JS dependencies directly into the HTML output.", "It securely injects SQL queries directly into the database without needing PDO.", "It manages the instantiation of objects and their dependencies automatically via reflection, promoting loose coupling and easier testing.", "It is a Docker container specifically optimized for running PHP applications." },
                    2, "A DI Container automatically resolves and injects class dependencies using Reflection, eliminating hardcoded `new` instantiations. Assuming it's a Docker container is a fundamental misunderstanding. DI Containers make enterprise PHP applications modular, testable, and maintainable.",
                    skillId: 7),
                CreateQuestion(id++, "How does the Nullsafe Operator (`?->`) work in PHP 8?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Backend,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "It checks if an array index is null and automatically removes it.", "It safely converts null values into empty strings to prevent database errors.", "It is used to explicitly declare that a function will return null.", "It allows reading properties and calling methods on an object; if the object evaluates to null, the entire chain short-circuits and evaluates to null without throwing an error." },
                    3, "The `?->` operator safely navigates a chain of objects; if any property/method is null, execution stops and returns null instead of throwing a fatal 'Call to a member function on null' error. It eliminates massive blocks of `if (!is_null($obj))` boilerplate.",
                    skillId: 7),
                CreateQuestion(id++, "What is the fundamental difference in execution architecture between `mod_php` and `PHP-FPM`?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Backend,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "`PHP-FPM` runs as an independent FastCGI process manager separate from the web server, whereas `mod_php` embeds the PHP interpreter directly inside the Apache process.", "`mod_php` is asynchronous and non-blocking, while `PHP-FPM` is synchronous.", "There is no difference; `PHP-FPM` is just an updated alias for `mod_php`.", "`PHP-FPM` is only for Nginx, while `mod_php` is only for Apache." },
                    0, "`PHP-FPM` maintains a pool of persistent PHP workers separate from the web server, vastly improving performance and scalability over `mod_php`, which forces Apache to load PHP into every request. Understanding this architecture is vital for senior DevOps and backend scaling.",
                    skillId: 7),
                CreateQuestion(id++, "How does PHP's Garbage Collector handle circular references?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Backend,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "It runs a synchronous cycle-collection algorithm periodically that identifies and cleans up unreachable objects referencing each other.", "It throws a fatal 'Circular Reference' exception at runtime.", "It relies entirely on the operating system to forcefully reclaim the memory when the server runs out.", "It cannot handle them; circular references always result in permanent memory leaks in PHP." },
                    0, "PHP utilizes a synchronous cycle-collection algorithm to find and destroy circular references (Object A references Object B, which references Object A). Assuming PHP leaks memory permanently ignores its sophisticated GC engine. This knowledge is crucial for long-running daemon processes.",
                    skillId: 7),
                CreateQuestion(id++, "What is the primary use case for `WeakMap` introduced in PHP 8?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Backend,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "It stores primitive variables with weak typing, ignoring `strict_types`.", "It creates an array that is completely hidden from the `var_dump()` output for security.", "It maps weak cryptographic keys to user sessions.", "It allows associating data with objects without preventing those objects from being garbage collected when no other strong references exist." },
                    3, "`WeakMap` stores object references without incrementing their reference count, allowing the GC to delete them when no other strong references remain. It prevents memory leaks in caching layers. Assuming it hides variables is completely incorrect.",
                    skillId: 7),
                CreateQuestion(id++, "In PHP OOP, what is a common pitfall of utilizing the Singleton design pattern heavily?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Backend,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "It introduces global state disguised as an object, tightly coupling code and making unit testing extremely difficult due to hidden dependencies.", "It automatically exposes sensitive data to the global `$_SESSION` array.", "It prevents the application from utilizing any namespaces.", "It causes severe memory leaks because the Singleton instance is duplicated every time it is called." },
                    0, "The Singleton pattern introduces hidden global state, tightly coupling classes and making unit testing nearly impossible because state persists between tests. Assuming it causes memory leaks misses the architectural danger. Senior developers vastly prefer Dependency Injection over Singletons.",
                    skillId: 7),
            });


            // ═══════════════════════════════════════════════════════════════════════════════
            // FRONTEND (JavaScript)
