            questions.AddRange(new[]
            {
                CreateQuestion(id++, "What is the primary difference between `let` and `const` in JavaScript?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "`const` is globally scoped, while `let` is locally scoped.", "`const` variables must be uppercase, while `let` variables must be lowercase.", "`let` is used for strings, while `const` is used for numbers.", "`const` declares a block-scoped variable that cannot be reassigned, while `let` declares a block-scoped variable that can be reassigned." },
                    3, "`const` prevents reassignment, whereas `let` allows it. Beginners often default to `let` for everything. Using `const` by default communicates intent and prevents accidental mutations, making code vastly more predictable and bug-resistant. Both are strictly block-scoped.",
                    skillId: 2),
                CreateQuestion(id++, "Which method is used to print messages to the web console for debugging?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "`document.write()`", "`print()`", "`System.out.println()`", "`console.log()`" },
                    3, "`console.log()` is the universal debugging tool in JavaScript, outputting variables directly to the browser console. Mistaking it for `print()` (Python) or `document.write()` (which overwrites the entire HTML) is a common beginner pitfall.",
                    skillId: 2),
                CreateQuestion(id++, "Which of the following is NOT a primitive data type in JavaScript?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "Boolean", "Number", "Object", "String" },
                    2, "`Object` is a complex, reference type, while String, Boolean, and Number are primitives (passed by value, immutable). Misunderstanding primitives vs objects leads to profound bugs regarding object mutation and memory references.",
                    skillId: 2),
                CreateQuestion(id++, "What is the difference between `==` and `===` in JavaScript?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "`==` is for integers, while `===` is for floating-point numbers.", "`===` is used only for comparing objects, while `==` is for primitives.", "`==` assigns a value, while `===` compares values.", "`==` compares value after type coercion, while `===` strictly compares both value and type without coercion." },
                    3, "`===` is strict equality, checking both type and value. `==` uses loose coercion (e.g., `\"2\" == 2` is true), which causes infamous, hard-to-track bugs. Best practice universally dictates using `===` to ensure type safety in logic.",
                    skillId: 2),
                CreateQuestion(id++, "What does DOM stand for in JavaScript programming?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "Data Object Management", "Dynamic Output Method", "Document Oriented Module", "Document Object Model" },
                    3, "DOM stands for Document Object Model. It is the crucial programming interface provided by the browser that represents HTML as a tree of objects, allowing JavaScript to dynamically read, alter, and style the web page in real-time.",
                    skillId: 2),
                CreateQuestion(id++, "How do you correctly attach a click event to an HTML button element?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "`button.attachEvent('onclick', myFunction);`", "`button.addEventListener('click', myFunction);`", "`button.onClick(myFunction);`", "`button.eventListener('click', myFunction);`" },
                    1, "`addEventListener('click', fn)` is the modern, non-destructive way to attach events. Using older methods like `onclick` overwrites any existing handlers. Mastering `addEventListener` is step one of interactive web development.",
                    skillId: 2),
                CreateQuestion(id++, "What does the `typeof` operator do in JavaScript?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "It converts a variable into a string.", "It casts a variable into a specific type.", "It checks if a variable exists in the global scope.", "It returns a string indicating the data type of the unevaluated operand." },
                    3, "`typeof` returns a string representing the type (e.g., `'string'`, `'number'`, `'object'`). It does not cast or convert data. Knowing how to use `typeof` is essential for defensive programming and input validation.",
                    skillId: 2),
                CreateQuestion(id++, "Which array method adds one or more elements to the end of an array and returns the new length?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "`push()`", "`unshift()`", "`shift()`", "`pop()`" },
                    0, "`push()` adds an item to the end of an array. Confusing it with `unshift()` (adds to the beginning) or `pop()` (removes from the end) breaks data structures. It is the most common array manipulation method in JS.",
                    skillId: 2),
                CreateQuestion(id++, "What syntax is used to create Template Literals (Template Strings) in ES6?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "Double quotes (`\" \"`)", "Single quotes (`' '`)", "Backticks (`` ` ``)", "Curly braces (`{ }`)" },
                    2, "Template literals use backticks (`` ` ``) and allow multi-line strings and easy variable interpolation via `${var}`. Trying to interpolate with single or double quotes fails. It vastly improves string readability over older concatenation methods.",
                    skillId: 2),
                CreateQuestion(id++, "What is the difference between `null` and `undefined` in JavaScript?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "`null` means a variable has been declared but not assigned a value, while `undefined` is an intentional assignment of 'no value'.", "`null` is used for numbers, while `undefined` is used for strings.", "There is no difference; they are exactly the same.", "`undefined` means a variable has been declared but not assigned a value, while `null` is an intentional assignment of 'no value'." },
                    3, "`undefined` is the default state of unassigned variables. `null` is an explicit, intentional absence of an object. Confusing them causes strict equality checks to fail. Senior developers use `null` to explicitly clear objects from memory.",
                    skillId: 2),
                CreateQuestion(id++, "What is the correct syntax for an `if` statement in JavaScript?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "`if i == 5 then { }`", "`if (i == 5) then { }`", "`if i = 5 { }`", "`if (i == 5) { }`" },
                    3, "`if (condition) { }` is the strict syntax. Attempting to use `then` or omitting parentheses (like in Python or Swift) will throw syntax errors. Grasping strict C-style syntax is necessary for writing functional JS.",
                    skillId: 2),
                CreateQuestion(id++, "Which syntax correctly defines an ES6 arrow function?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "`function sum(a, b) => { return a + b; }`", "`const sum = (a, b) => { return a + b; }`", "`const sum => (a, b) { return a + b; }`", "`let sum = (a, b) -> { return a + b; }`" },
                    1, "`() => {}` is the ES6 arrow function syntax, offering a concise way to write functions. Attempting to mix `function` keywords with arrows or using `->` causes syntax errors. Arrow functions also elegantly solve `this` binding issues.",
                    skillId: 2),
                CreateQuestion(id++, "What does `NaN` represent in JavaScript?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "'Null-and-Nil', indicating an empty object.", "'Native-App-Network', an API request timeout.", "'New-Array-Node', a special data structure.", "'Not-a-Number', indicating a failed number parsing or invalid mathematical operation." },
                    3, "`NaN` means 'Not-a-Number'. It occurs when math fails (e.g., dividing a string by a number). A massive gotcha is that `typeof NaN` returns `'number'`, and `NaN === NaN` is false! Using `Number.isNaN()` is the safe way to check it.",
                    skillId: 2),
                CreateQuestion(id++, "JavaScript is described as a single-threaded language. What does this mean?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "It has only one call stack and can only execute one piece of code at a time.", "It can only handle one user request per server.", "It can only run on a single-core processor.", "It does not support asynchronous programming." },
                    0, "JS has a single call stack, meaning it processes one command at a time on the main thread. Assuming it can multi-task natively ignores its architecture. To remain non-blocking, JS relies heavily on the Event Loop and asynchronous callbacks.",
                    skillId: 2),
                CreateQuestion(id++, "What is the purpose of `JSON.stringify()` in JavaScript?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "It parses a JSON string into a JavaScript object.", "It encrypts an object for secure network transmission.", "It converts a JavaScript object or value to a JSON string.", "It formats a string to be displayed nicely in the DOM." },
                    2, "`JSON.stringify()` serializes objects into a JSON string, vital for saving data to LocalStorage or sending API requests via `fetch`. Confusing it with `JSON.parse()` (which does the reverse) breaks data payloads entirely.",
                    skillId: 2),
                CreateQuestion(id++, "What is a Closure in JavaScript?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "A memory optimization technique that automatically deletes unused variables.", "A built-in method to securely close an active WebSocket connection.", "A syntax rule that requires every open bracket `{` to have a matching closing bracket `}`.", "A feature where an inner function retains access to the outer (enclosing) function's variables even after the outer function has returned." },
                    3, "A closure 'remembers' its lexical environment. This allows inner functions to access variables from a finished outer function. Misunderstanding closures causes severe memory leaks. They are the backbone of data privacy (private variables) in JS.",
                    skillId: 2),
                CreateQuestion(id++, "What is Event Delegation in the DOM?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "Attaching a single event listener to a parent element to manage events for all its current and future children via event bubbling.", "Preventing an event from bubbling up the DOM tree.", "Delegating the heavy lifting of event processing to a Web Worker.", "Passing an event object as an argument to multiple different functions." },
                    0, "Event Delegation places one listener on a parent instead of hundreds on children, drastically saving RAM and automatically handling newly appended elements. Assuming listeners must go on individual buttons is a junior mistake that destroys page performance.",
                    skillId: 2),
                CreateQuestion(id++, "What are the three possible states of a JavaScript Promise?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "Pending, Fulfilled, Rejected", "Open, Processing, Closed", "Started, Paused, Stopped", "Waiting, Executing, Finished" },
                    0, "A Promise is either Pending (working), Fulfilled (success), or Rejected (error). Misunderstanding these states leads to unhandled promise rejections and silent failures. They are the modern standard for handling async operations.",
                    skillId: 2),
                CreateQuestion(id++, "How does the value of the `this` keyword get determined in JavaScript (excluding arrow functions)?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "It is determined solely by the lexical scope at compile time.", "It always refers to the global `window` object.", "It is determined by how the function is called (the execution context), not where the function was declared.", "It always refers to the exact file where the function is written." },
                    2, "In standard functions, `this` is bound at the call site (how the function is executed). Arrow functions, however, bind `this` lexically. Confusing this behavior is arguably the number one source of bugs in object-oriented JavaScript.",
                    skillId: 2),
                CreateQuestion(id++, "What is Hoisting in JavaScript?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "The process of automatically upgrading a variable from `let` to `var` if it causes an error.", "A performance feature that pushes critical scripts to the top of the HTML `<head>`.", "The automatic conversion of a string into an integer.", "JavaScript's default behavior of moving variable and function declarations to the top of their respective scopes during the compilation phase." },
                    3, "Hoisting pulls declarations (not initializations) to the top of the scope. While `var` is hoisted and accessible as `undefined`, `let` and `const` are hoisted but remain in a 'Temporal Dead Zone', throwing reference errors if accessed early.",
                    skillId: 2),
                CreateQuestion(id++, "What is the primary difference between the array methods `map()` and `forEach()`?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "`map()` executes asynchronously, while `forEach()` executes synchronously.", "`map()` returns a completely new array containing the results, while `forEach()` returns `undefined` and is used for side effects.", "`map()` iterates over objects, while `forEach()` iterates over arrays.", "`forEach()` returns a new array, while `map()` mutates the original array in place." },
                    1, "`map()` transforms data and returns a brand-new array, perfectly aligning with immutable functional programming. `forEach()` returns `undefined` and is used for side-effects (like mutating DOM). Using `map()` without utilizing the returned array is an anti-pattern.",
                    skillId: 2),
                CreateQuestion(id++, "What does the `await` keyword do in an `async` function?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "It pauses the execution of the `async` function until the Promise is resolved or rejected, yielding control back to the event loop.", "It automatically resolves all pending Promises in the application.", "It forcefully terminates a hanging Promise after a timeout.", "It blocks the entire browser's main thread until the network request finishes." },
                    0, "`await` effectively pauses the async function, allowing the browser to render UI or run other tasks on the event loop until the Promise resolves. Believing it blocks the main thread completely misunderstands JS concurrency.",
                    skillId: 2),
                CreateQuestion(id++, "What does the Spread operator (`...`) do when used on an array?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "It expands the array into its individual elements, allowing for easy copying or merging of arrays.", "It converts the array into a comma-separated string.", "It compresses an array to save memory.", "It creates an infinite loop over the array elements." },
                    0, "The spread operator `...` unpacks elements. It is the cleanest, most idiomatic way to shallow copy an array (`[...arr]`) or merge them. Assuming it compresses data is false. It heavily reduces verbose looping syntax.",
                    skillId: 2),
                CreateQuestion(id++, "What is Destructuring Assignment in JavaScript?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "A syntax that makes it possible to unpack values from arrays, or properties from objects, into distinct, individual variables.", "A mechanism that destroys an object to free up RAM.", "A security feature that scrambles JSON data before saving it to LocalStorage.", "A method to delete specific indexes from an array permanently." },
                    0, "Destructuring concisely extracts object properties (`const { name } = user`). It drastically cleans up code, especially when dealing with nested API JSON responses. Misunderstanding it leads to heavily repetitive dot-notation.",
                    skillId: 2),
                CreateQuestion(id++, "Why doesn't `setTimeout(fn, 0)` execute immediately?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "It waits for the user to trigger a click event before running.", "It pushes the callback to the Task Queue, meaning it will only execute after the current call stack has completely finished clearing.", "The browser enforces a minimum delay of 1000 milliseconds for security reasons.", "It is a bug in the V8 engine that causes a micro-delay." },
                    1, "`setTimeout` delegates the timer to the Web APIs. Even at 0ms, the callback is pushed to the Task Queue, meaning it must wait for the current synchronous Call Stack to completely finish. Understanding this is crucial for preventing UI blocking.",
                    skillId: 2),
                CreateQuestion(id++, "How does Prototypal Inheritance work in JavaScript?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "Inheritance is strictly managed by importing specific files via CommonJS.", "Classes inherit from base classes strictly through compile-time static types.", "Objects inherit properties and methods directly from other objects via a hidden `[[Prototype]]` linkage chain.", "Objects physically copy all methods from their parent upon instantiation." },
                    2, "JS objects link to other objects via a `[[Prototype]]` chain. When a property isn't found, JS walks up the chain. Assuming JS uses strict classical inheritance (like Java) misses the dynamic, flexible power of object composition via prototypes.",
                    skillId: 2),
                CreateQuestion(id++, "What is the difference between a Shallow Copy and a Deep Copy in JavaScript?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "A shallow copy is faster but temporary, while a deep copy is permanent.", "A shallow copy is stored in RAM, while a deep copy is stored on the hard drive.", "A shallow copy copies only strings, while a deep copy copies numbers and booleans too.", "A shallow copy copies the top-level properties but shares nested object references, while a deep copy recursively copies everything, creating entirely independent objects." },
                    3, "Shallow copies duplicate the first level, but nested objects remain shared references (mutating the copy mutates the original!). Deep copies clone entirely. Relying on shallow copies for complex state (like in React) causes catastrophic render bugs.",
                    skillId: 2),
                CreateQuestion(id++, "What does placing `'use strict';` at the top of a JavaScript file accomplish?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "It enforces a stricter parsing and error handling model, preventing accidental globals, silent failing assignments, and duplicate property names.", "It prevents the use of asynchronous functions in the file.", "It forces the browser to strictly type-check all variables like in TypeScript.", "It drastically slows down the execution speed to allow for easier debugging." },
                    0, "`'use strict';` enforces defensive coding by throwing errors for bad practices (like undeclared variables creating globals). Assuming it acts as a compiler slows down development. It is the standard for modern, secure JS.",
                    skillId: 2),
                CreateQuestion(id++, "What is the primary difference between `call()` and `apply()` when invoking a function?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "`call()` permanently binds the `this` context, while `apply()` only binds it temporarily.", "`call()` takes arguments separately as a comma-separated list, while `apply()` takes arguments as a single array.", "`call()` can only be used on objects, while `apply()` can only be used on arrays.", "`apply()` executes asynchronously, while `call()` executes synchronously." },
                    1, "`call()` takes comma-separated arguments, `apply()` takes an array. They explicitly set the `this` context for a single invocation. Confusing them causes `TypeError`s. `bind()` is used to permanently lock the context for later execution.",
                    skillId: 2),
                CreateQuestion(id++, "What is the core difference between `localStorage` and `sessionStorage` in the browser?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "`sessionStorage` is encrypted automatically, while `localStorage` is completely visible to the user.", "`localStorage` has a limit of 5MB, while `sessionStorage` has unlimited storage capacity.", "`localStorage` persists data even after the browser is closed, while `sessionStorage` clears data when the specific tab or window is closed.", "`sessionStorage` can be shared across different domains, while `localStorage` cannot." },
                    2, "`localStorage` is permanent until cleared, excellent for user settings. `sessionStorage` dies when the tab closes, perfect for sensitive mid-transaction data. Mixing them up causes major security flaws or annoying user experiences.",
                    skillId: 2),
                CreateQuestion(id++, "In the context of the JavaScript Event Loop, what is the difference between Macrotasks and Microtasks?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "Microtasks (like Promise callbacks) have higher priority and will completely drain their queue before the next Macrotask (like `setTimeout`) is allowed to run.", "Macrotasks have higher priority and execute immediately, while Microtasks are pushed to a background Web Worker.", "Microtasks are used exclusively for DOM rendering, while Macrotasks are used for network requests.", "There is no difference; they are just two different names for the same Callback Queue." },
                    0, "The Event Loop checks the Microtask Queue (Promises) first, draining it entirely before processing a single Macrotask (setTimeout). If Microtasks keep generating more Microtasks, the UI thread will freeze. Knowing this hierarchy is vital for senior-level performance tuning.",
                    skillId: 2),
                CreateQuestion(id++, "What causes a 'Detached DOM Element' memory leak in JavaScript?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "Making too many `fetch()` requests without waiting for them to resolve.", "Failing to close a `<script>` tag in the HTML file properly.", "Using too many CSS animations on a single element.", "Removing an element from the DOM tree, but still holding a reference to it inside a JavaScript variable or closure, preventing garbage collection." },
                    3, "If you remove a DOM element but a JS object/array still references it, the Garbage Collector cannot free its memory, causing a 'Detached DOM Leak'. Over time, this crashes Single Page Applications (SPAs). Proper teardown logic is critical.",
                    skillId: 2),
                CreateQuestion(id++, "How does the Mark-and-Sweep Garbage Collection algorithm work in modern V8 JavaScript?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "It forces the developer to manually call `gc()` to clear out dead variables.", "It starts from the global 'roots', traverses all reachable objects, 'marks' them as active, and then 'sweeps' away unreached objects to free memory.", "It blindly clears all memory every 5 seconds regardless of what is currently executing.", "It counts the number of times a variable is referenced and deletes it when the count hits zero." },
                    1, "The Mark-and-Sweep GC traces all references starting from the global object. Anything it cannot reach is marked as garbage and swept from memory. Assuming it relies on reference counting ignores how V8 solves the 'circular reference' memory leak problem.",
                    skillId: 2),
                CreateQuestion(id++, "What is Currying in JavaScript functional programming?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "The ability to securely hash user passwords on the client side.", "The process of optimizing array sorting algorithms to run in O(n log n) time.", "The technique of transforming a function that takes multiple arguments into a sequence of functions that each take a single argument.", "The automatic conversion of recursive loops into standard while loops." },
                    2, "Currying transforms `f(a, b)` into `f(a)(b)`, allowing partial application of functions. It creates highly reusable, composable factory functions in functional programming. Misunderstanding it limits the modularity of complex logic architectures.",
                    skillId: 2),
                CreateQuestion(id++, "What is the primary use case of a Generator function (`function*`) in JavaScript?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "To automatically generate random cryptographic keys for WebSockets.", "To instantly generate thousands of HTML elements securely.", "To pause and resume execution on demand, generating a sequence of values lazily over time without blocking the main thread.", "To spawn a new multi-threaded process outside the browser sandbox." },
                    2, "Generators use `yield` to pause execution, maintaining internal state, and yielding values on demand. They are incredibly powerful for iterating over massive data sets or creating complex state machines without blocking the UI thread.",
                    skillId: 2),
                CreateQuestion(id++, "What is the key advantage of using a `WeakMap` over a standard `Map` in JavaScript?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "A `WeakMap` holds 'weak' references to its object keys, meaning if there are no other references to the key object, it will be automatically garbage collected.", "A `WeakMap` is synchronous and inherently thread-safe.", "A `WeakMap` can use strings and numbers as keys, while a standard `Map` can only use objects.", "A `WeakMap` maintains the insertion order of its elements much faster than a standard `Map`." },
                    0, "`WeakMap` uses objects as keys but holds them 'weakly'. If the app deletes all other references to the key object, the GC immediately destroys the WeakMap entry. It is the ultimate tool for caching data on DOM elements without causing memory leaks.",
                    skillId: 2),
                CreateQuestion(id++, "What is the primary purpose of JavaScript `Symbol` primitives?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "They replace standard strings for faster database querying.", "They create guaranteed unique identifiers, often used to add hidden or private properties to objects without risking name collisions.", "They are used to securely store authentication tokens in memory.", "They are used to draw SVGs directly to the HTML canvas." },
                    1, "Symbols are immutable, unique primitives. They are used to create hidden object properties that won't show up in `for...in` loops or `Object.keys()`, effectively allowing a form of 'private' properties before formal private class fields `#` existed.",
                    skillId: 2),
                CreateQuestion(id++, "What does a JavaScript `Proxy` object allow you to do?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "It safely executes arbitrary user-submitted strings as JavaScript code.", "It allows you to intercept and redefine fundamental operations on an object, such as property lookup, assignment, enumeration, and function invocation.", "It serves as a polyfill to support ES6 features on older browsers.", "It automatically routes network requests through a secure VPN." },
                    1, "Proxies wrap an object and trap fundamental operations (like 'get' and 'set'). They are the hidden magic behind reactivity systems in modern frameworks like Vue 3, allowing the framework to automatically update the DOM when a variable changes.",
                    skillId: 2),
                CreateQuestion(id++, "How do Web Workers achieve true multithreading in the browser?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "They run scripts in background threads independent of the main UI thread, communicating strictly via message passing since they cannot access the DOM.", "They create multiple duplicate DOM trees to render UI components in parallel.", "They bypass the V8 engine and execute code directly on the GPU.", "They utilize the HTML5 `<canvas>` element to execute background logic." },
                    0, "Web Workers spin up true OS-level threads. Because the DOM is not thread-safe, workers cannot access it; they communicate via `postMessage`. Offloading heavy math/crypto to a Worker is the only way to keep 60fps animations smooth during high CPU load.",
                    skillId: 2),
                CreateQuestion(id++, "What is the core difference between Debouncing and Throttling when optimizing high-frequency events like scrolling?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "Debouncing speeds up the function execution time, while Throttling limits the memory usage.", "Debouncing is strictly for mouse events, while Throttling is for keyboard events.", "Debouncing ensures a function runs only after a pause in events, while Throttling ensures a function runs at a steady, maximum periodic rate during the events.", "There is no difference; they are synonymous terms for the exact same optimization algorithm." },
                    2, "Debouncing groups a rapid burst of events into a single execution (waits for a pause). Throttling enforces a maximum execution rate (fires every X ms). Using Debounce on a scroll-spy breaks it, using Throttle fixes it. Knowing when to apply which is critical.",
                    skillId: 2),
                CreateQuestion(id++, "What is Tail Call Optimization (TCO) in JavaScript?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "An algorithm that minifies JavaScript files by removing the 'tail' whitespace.", "An engine optimization that prevents stack overflow errors in recursive functions by reusing the current stack frame if the recursive call is the very last action.", "A memory management feature that deletes variables as soon as they are no longer needed.", "A process that moves all `<script>` tags to the 'tail' end of the HTML body." },
                    1, "TCO optimizes recursive functions by dropping the previous stack frame if the recursion is the final return, preventing 'Maximum Call Stack Size Exceeded'. Unfortunately, engine support varies, so senior developers often rewrite deep recursion as iterative loops.",
                    skillId: 2),
                CreateQuestion(id++, "What is the primary benefit of using `Object.defineProperty()` over standard dot notation assignment?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "It allows the assignment of functions to an object, which dot notation cannot do.", "It automatically deep clones the value being assigned.", "It executes 10x faster than standard dot notation in modern browsers.", "It allows precise control over property attributes, making properties read-only (writable: false), hidden from loops (enumerable: false), or undeletable." },
                    3, "`Object.defineProperty()` allows meta-programming by defining if a property can be iterated, modified, or deleted. This is how libraries freeze configuration objects or create computed getter/setter properties securely, preventing developer manipulation.",
                    skillId: 2),
                CreateQuestion(id++, "How do the Optional Chaining (`?.`) and Nullish Coalescing (`??`) operators work together beautifully?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "`?.` safely attempts to read a deeply nested property without throwing an error if it's null/undefined, and `??` provides a fallback value strictly if the result is null/undefined.", "`?.` checks if a function is asynchronous, and `??` pauses it.", "`?.` checks if a variable is an array, and `??` extracts the first element.", "They cannot be used together as they serve conflicting purposes in the AST compiler." },
                    0, "Using `user?.address?.zip ?? '00000'` prevents fatal crashes on missing objects and supplies a clean default. Combining them eliminates dozens of lines of defensive `if/else` checks, making data parsing incredibly clean and fail-safe.",
                    skillId: 2),
                CreateQuestion(id++, "What is the key architectural difference between CommonJS (`require()`) and ES6 Modules (`import`)?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "CommonJS encrypts the modules before loading, while ES6 Modules load in plaintext.", "CommonJS is used strictly in the browser, while ES6 Modules are strictly for Node.js.", "CommonJS is synchronous and loads modules dynamically at runtime, whereas ES6 Modules are asynchronous and statically analyzable at compile time.", "There is no architectural difference; `import` is simply syntactic sugar for `require()`." },
                    2, "ES6 Modules (`import`) are statically analyzed, allowing bundlers like Webpack to 'tree-shake' (remove unused code) before runtime, vastly reducing bundle size. CommonJS (`require`) is dynamic, making tree-shaking nearly impossible. Moving to ES6 Modules is a modern JS imperative.",
                    skillId: 2),
                CreateQuestion(id++, "Why is `requestAnimationFrame` vastly superior to `setTimeout` for creating smooth browser animations?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Frontend,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "It allows developers to write animations in C++ and compile them to WebAssembly seamlessly.", "It completely bypasses the JavaScript main thread and runs the animation natively on the GPU.", "It syncs strictly with the browser's display refresh rate (usually 60fps) and pauses when the tab is inactive, saving battery and CPU while preventing screen tearing.", "It automatically converts CSS animations into WebGL shaders." },
                    2, "`requestAnimationFrame` aligns precisely with the monitor's v-sync, smoothing animations and preventing battery drain when the tab is backgrounded. Using `setInterval` forces the CPU to calculate frames that might never be drawn, creating stutter and heat.",
                    skillId: 2),
            });


            // ═══════════════════════════════════════════════════════════════════════════════
            // DEVOPS / TOOLS (Git)
            // ═══════════════════════════════════════════════════════════════════════════════

            questions.AddRange(new[]
            {
                CreateQuestion(id++, "What is the primary function of the `git init` command?",
                    QuestionCategory.Technical, JobTitleRoleFamily.DevOps,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "It downloads an existing repository from a remote server.", "It creates a new, empty Git repository or reinitializes an existing one in the current directory.", "It automatically connects your local folder to a GitHub account.", "It deletes all current Git history and starts fresh." },
                    1, "`git init` creates the hidden `.git` directory, which houses the staging area, object database, and config. Without it, version control doesn't exist in that folder. A common mistake is running this inside an already initialized repository.",
                    skillId: 34),
                CreateQuestion(id++, "What does the `git clone` command do?",
                    QuestionCategory.Technical, JobTitleRoleFamily.DevOps,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "It duplicates a local branch to test new features.", "It copies the most recent commit into a new branch.", "It creates a local copy of a remote repository, including all of its files, branches, and commit history.", "It uploads your local repository to a remote server." },
                    2, "`git clone` is the starting point for contributing to existing projects. It pulls down the `.git` history and checks out the default branch. Misunderstanding this causes beginners to try downloading ZIP files instead, losing all Git functionality.",
                    skillId: 34),
                CreateQuestion(id++, "Which command allows you to see which files are modified, staged, or untracked in your working directory?",
                    QuestionCategory.Technical, JobTitleRoleFamily.DevOps,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "`git show`", "`git status`", "`git diff`", "`git log`" },
                    1, "`git status` is arguably the most used Git command. It tells you exactly what Git sees in the Working Directory and Staging Area. Failing to check `git status` often leads to committing the wrong files.",
                    skillId: 34),
                CreateQuestion(id++, "What happens when you run `git add .`?",
                    QuestionCategory.Technical, JobTitleRoleFamily.DevOps,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "It resolves all current merge conflicts automatically.", "It stages all modified and new files in the current directory (and subdirectories) to be included in the next commit.", "It commits all changes directly to the remote repository.", "It adds a new remote tracking server." },
                    1, "`git add .` stages all changes. The staging area allows developers to carefully curate what goes into a commit. Believing `add` sends files to the server is a fundamental misconception; it only prepares them locally.",
                    skillId: 34),
                CreateQuestion(id++, "What is the purpose of the `-m` flag in the `git commit -m \"message\"` command?",
                    QuestionCategory.Technical, JobTitleRoleFamily.DevOps,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "It 'modifies' the previous commit instead of creating a new one.", "It creates a 'master' commit that cannot be reverted.", "It merges the commit immediately into the main branch.", "It allows you to pass a commit message directly in the command line without opening a text editor." },
                    3, "The `-m` flag saves time by bypassing the default terminal text editor (like Vim). However, for complex commits, omitting `-m` is better as it allows multi-line, detailed commit messages describing the 'why' behind the change.",
                    skillId: 34),
                CreateQuestion(id++, "What is the fundamental difference between Git and GitHub?",
                    QuestionCategory.Technical, JobTitleRoleFamily.DevOps,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "There is no difference; they are synonymous terms for the exact same tool.", "Git is a distributed version control software running locally, while GitHub is a cloud-based hosting service for Git repositories.", "Git requires a paid subscription, whereas GitHub is always free.", "Git is exclusively for Linux, while GitHub is for Windows." },
                    1, "Git is the core engine running on your machine. GitHub is a Microsoft-owned website that hosts Git repositories. Confusing the tool (Git) with the hosting provider (GitHub, GitLab, Bitbucket) is a very common beginner mistake.",
                    skillId: 34),
                CreateQuestion(id++, "What is the primary purpose of the `git push` command?",
                    QuestionCategory.Technical, JobTitleRoleFamily.DevOps,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "To upload local repository content and commit history to a remote repository.", "To permanently delete a remote branch.", "To forcefully overwrite the main branch with experimental code.", "To download updates from the remote repository to your local machine." },
                    0, "`git push` synchronizes your local branch commits with the remote server. Without it, your work only exists on your hard drive. Failing to push means teammates cannot see or collaborate on your code.",
                    skillId: 34),
                CreateQuestion(id++, "What does the `git pull` command essentially do behind the scenes?",
                    QuestionCategory.Technical, JobTitleRoleFamily.DevOps,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "It pulls the latest code from the remote server but keeps it safely separated from your working directory.", "It runs `git fetch` to download new data, and immediately runs `git merge` to integrate it into the current branch.", "It forcefully replaces your local branch with the remote branch, destroying uncommitted work.", "It reverses the most recent commit." },
                    1, "`git pull` is a combination of `git fetch` (download data) and `git merge` (integrate data). Understanding this two-step process is vital because a `pull` can trigger immediate, unexpected merge conflicts in your working directory.",
                    skillId: 34),
                CreateQuestion(id++, "In Git terminology, what is a 'branch'?",
                    QuestionCategory.Technical, JobTitleRoleFamily.DevOps,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "A secure folder where sensitive passwords are kept out of version control.", "A specific snapshot of code marked with a version number.", "A copy of the entire repository stored on a different physical hard drive.", "An independent line of development that allows you to work on features or fixes without affecting the main codebase." },
                    3, "Branches are cheap, lightweight pointers in Git. They allow parallel development without breaking the main production code. A lack of branching leads to 'merge hell' where multiple developers constantly overwrite each other's work.",
                    skillId: 34),
                CreateQuestion(id++, "Which command is used to switch between different branches in a Git repository?",
                    QuestionCategory.Technical, JobTitleRoleFamily.DevOps,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "`git branch --switch`", "`git change`", "`git checkout` (or `git switch`)", "`git move`" },
                    2, "`git checkout` (or the newer, safer `git switch`) updates files in your working directory to match the target branch. Attempting to code on the wrong branch is a frequent source of lost work.",
                    skillId: 34),
                CreateQuestion(id++, "How can you view the detailed history of commits made in the repository?",
                    QuestionCategory.Technical, JobTitleRoleFamily.DevOps,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "`git show`", "`git log`", "`git commits`", "`git history`" },
                    1, "`git log` prints the commit history. Adding flags like `--oneline` or `--graph` provides concise, readable trees. Not knowing how to view the log makes it impossible to track down when bugs were introduced.",
                    skillId: 34),
                CreateQuestion(id++, "What is the purpose of a `.gitignore` file?",
                    QuestionCategory.Technical, JobTitleRoleFamily.DevOps,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "To explicitly tell Git which files and directories should not be tracked or committed (like build artifacts or sensitive secrets).", "To delete files that are no longer needed in the project.", "To store passwords securely so they are encrypted before being pushed.", "To temporarily disable Git tracking for the entire repository." },
                    0, "`.gitignore` is crucial for keeping repositories clean. Committing `node_modules`, `.env` files, or compiled binaries bloats the repository and causes severe security risks. Git ignores these files based on rules in this text file.",
                    skillId: 34),
                CreateQuestion(id++, "What does the `git merge` command do?",
                    QuestionCategory.Technical, JobTitleRoleFamily.DevOps,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "It integrates the changes from one branch into the current active branch.", "It pushes your branch to a remote repository and opens a Pull Request.", "It combines multiple commits into a single, cleaner commit.", "It deletes a branch and combines its history with the main branch." },
                    0, "`git merge` combines branches. It attempts to automatically weave the file changes together. If two developers edited the exact same line, a 'merge conflict' occurs, requiring manual human intervention.",
                    skillId: 34),
                CreateQuestion(id++, "In Git, what does the 'Working Directory' refer to?",
                    QuestionCategory.Technical, JobTitleRoleFamily.DevOps,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "The actual files on your local computer disk that you are currently viewing and editing.", "The staging area where files wait before being committed.", "The remote server where your code is hosted.", "The hidden `.git` folder where Git stores its internal tracking data." },
                    0, "The Working Directory is your local file system where you edit code. It is distinct from the Staging Area (index) and the Repository (history). Understanding these three 'trees' is the absolute key to mastering Git.",
                    skillId: 34),
                CreateQuestion(id++, "What does `HEAD` signify in Git?",
                    QuestionCategory.Technical, JobTitleRoleFamily.DevOps,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "The very first commit ever made in the repository.", "A reference pointer to the currently checked-out commit or branch in your working directory.", "A special command used to forcefully delete commits.", "The main branch on the remote server." },
                    1, "`HEAD` points to what you are currently looking at. Normally, it points to a branch reference (like `main`), which in turn points to a commit. Understanding HEAD is necessary for advanced commands like reset and rebase.",
                    skillId: 34),
                CreateQuestion(id++, "What does the `git remote add` command accomplish?",
                    QuestionCategory.Technical, JobTitleRoleFamily.DevOps,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "It automatically pushes all local changes to the internet.", "It connects your local Git repository to a remote server URL (like GitHub) and assigns it a short name (usually 'origin').", "It downloads missing files from a remote server.", "It adds a new developer to your GitHub organization." },
                    1, "`git remote add origin URL` tells your local Git where the remote server lives. 'origin' is just a standard convention, not a reserved keyword. Without a remote, you cannot push or pull code.",
                    skillId: 34),
                CreateQuestion(id++, "Conceptually, what is a Git 'commit'?",
                    QuestionCategory.Technical, JobTitleRoleFamily.DevOps,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "A backup file uploaded to the cloud.", "A permanent snapshot of the staged changes in your repository at a specific point in time, accompanied by a message.", "A temporary save state that gets deleted when you close the terminal.", "A request to a senior developer to review your code." },
                    1, "A commit is an immutable snapshot. Unlike older version control (SVN) that stored 'deltas' (differences), Git stores complete snapshots. This makes branching incredibly fast but means large binary files bloat the repo permanently.",
                    skillId: 34),
                CreateQuestion(id++, "What is the difference between running `git rm file.txt` and just running `rm file.txt` in the terminal?",
                    QuestionCategory.Technical, JobTitleRoleFamily.DevOps,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "`git rm` deletes the file from disk and automatically stages the deletion for the next commit, whereas `rm` only deletes it from the disk.", "There is absolutely no difference.", "`git rm` deletes the file from the remote server instantly.", "`rm` deletes the file permanently, while `git rm` moves it to the recycle bin." },
                    0, "`git rm` stages the deletion. If you just use `rm`, Git sees a 'deleted' file in the working directory, but you still have to `git add` that deletion to stage it. `git rm` saves a step.",
                    skillId: 34),
                CreateQuestion(id++, "What is the crucial difference between `git fetch` and `git pull`?",
                    QuestionCategory.Technical, JobTitleRoleFamily.DevOps,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "`git pull` only updates branches, while `git fetch` updates tags.", "`git fetch` is faster than `git pull`.", "`git fetch` downloads remote changes but leaves your working directory untouched, while `git pull` downloads AND immediately attempts to merge them.", "`git fetch` forcefully overwrites local files, while `git pull` asks for permission." },
                    2, "`git fetch` is perfectly safe; it just updates your local `.git` data. `git pull` is aggressive; it fetches and immediately merges. Senior developers often prefer `fetch` to inspect changes before merging them.",
                    skillId: 34),
                CreateQuestion(id++, "Which command shows the line-by-line differences between your working directory and the staging area?",
                    QuestionCategory.Technical, JobTitleRoleFamily.DevOps,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "`git show`", "`git diff`", "`git log -p`", "`git compare`" },
                    1, "`git diff` shows unstaged changes. If you run `git add`, `git diff` shows nothing! You must use `git diff --staged` to see what is about to be committed. This is a massive point of confusion for beginners.",
                    skillId: 34),
                CreateQuestion(id++, "What is the primary difference between `git rebase` and `git merge`?",
                    QuestionCategory.Technical, JobTitleRoleFamily.DevOps,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "`git rebase` is used exclusively for remote branches, while `git merge` is for local branches.", "`git rebase` deletes the old branch, while `git merge` keeps it.", "`git merge` creates a new merge commit combining two histories, while `git rebase` rewrites history by moving the entire branch base to a new commit, creating a linear history.", "`git merge` can cause conflicts, but `git rebase` automatically resolves all conflicts safely." },
                    2, "`git merge` preserves complete chronological history (creating a diamond shape in the log). `git rebase` rewrites history, placing your branch changes strictly on top of the target branch. Rebase makes logs clean but is dangerous on public/shared branches.",
                    skillId: 34),
                CreateQuestion(id++, "What is the purpose of the `git stash` command?",
                    QuestionCategory.Technical, JobTitleRoleFamily.DevOps,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "It permanently deletes all untracked files from the repository.", "It temporarily shelves (saves) uncommitted changes in your working directory, allowing you to switch branches cleanly without committing half-finished work.", "It encrypts sensitive files before pushing them to a public repository.", "It combines the last 5 commits into a single commit to clean up the history." },
                    1, "`git stash` acts as a temporary clipboard for uncommitted work. It is invaluable when you need to urgently pull changes or switch branches to fix a bug without committing half-written code.",
                    skillId: 34),
                CreateQuestion(id++, "What is the difference between `git reset --soft` and `git reset --hard`?",
                    QuestionCategory.Technical, JobTitleRoleFamily.DevOps,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "`--soft` is reversible, but `--hard` requires an admin password.", "`--hard` pushes the reset to the remote server, while `--soft` keeps it local.", "`--soft` moves HEAD back but keeps your changes staged; `--hard` moves HEAD back and permanently destroys any uncommitted changes in your working directory.", "`--soft` only deletes files, while `--hard` deletes the entire branch." },
                    2, "`--hard` is dangerous: it deletes uncommitted work permanently. `--soft` is safe: it undoes the commit but leaves your files intact and staged. Misusing `--hard` is the #1 way developers accidentally delete their own work.",
                    skillId: 34),
                CreateQuestion(id++, "What does the `git cherry-pick <commit-hash>` command do?",
                    QuestionCategory.Technical, JobTitleRoleFamily.DevOps,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "It selectively pushes a single commit to the remote server while leaving others behind.", "It deletes a specific commit from the middle of your history.", "It highlights the most recent commit in your terminal GUI.", "It takes the exact changes introduced by a specific commit from another branch and applies them as a new commit on your current branch." },
                    3, "`cherry-pick` is a surgical tool. Instead of merging a whole branch, you grab one specific commit (like a hotfix) and apply it to your current branch. It is highly useful in release management.",
                    skillId: 34),
                CreateQuestion(id++, "How does Git represent a merge conflict inside a file?",
                    QuestionCategory.Technical, JobTitleRoleFamily.DevOps,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "By injecting standard conflict markers like `<<<<<<< HEAD`, `=======`, and `>>>>>>> branch-name` directly into the text file.", "By automatically deleting the file and placing both versions in a temporary folder.", "By locking the file system so you cannot open the file until you type `git resolve`.", "By highlighting the lines in red using terminal escape codes." },
                    0, "Git injects textual markers into conflicting files. You must manually open the file, decide which code to keep, delete the `<<<<<<<` markers, and then `git add` the file to resolve the conflict. Trusting auto-merge tools blindly can cause bugs.",
                    skillId: 34),
                CreateQuestion(id++, "What does it mean when Git says you are in a 'detached HEAD' state?",
                    QuestionCategory.Technical, JobTitleRoleFamily.DevOps,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "HEAD is pointing directly to a specific commit hash rather than a branch name. Any new commits made now will not belong to any branch and may be lost.", "The local repository has lost connection to the remote GitHub server.", "You have staged changes but have not committed them yet.", "The repository is corrupted and requires `git fsck` to repair the HEAD pointer." },
                    0, "Checking out a specific commit hash (instead of a branch name) detaches HEAD. Commits made here have no branch pointing to them. If you switch away, they become 'orphans' and the GC eventually deletes them. Always create a branch if you plan to commit here.",
                    skillId: 34),
                CreateQuestion(id++, "What is the crucial difference between `git revert` and `git reset`?",
                    QuestionCategory.Technical, JobTitleRoleFamily.DevOps,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "`git revert` deletes files, while `git reset` just unstages them.", "`git revert` creates a brand new commit that undoes changes (safe for pushed history), whereas `git reset` rewrites history by moving the branch pointer backward.", "There is no difference; they both safely undo the last commit.", "`git reset` only works on local branches, while `git revert` only works on remote branches." },
                    1, "`git revert` is the safe way to undo public commits because it moves history FORWARD (adding a new 'undo' commit). `git reset` deletes history BACKWARD, which will severely break the repository for teammates if the branch was already pushed.",
                    skillId: 34),
                CreateQuestion(id++, "When is it appropriate to use `git commit --amend`?",
                    QuestionCategory.Technical, JobTitleRoleFamily.DevOps,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "To modify the very last commit (e.g., fixing a typo in the commit message or adding a forgotten file) BEFORE it has been pushed to a shared remote repository.", "To forcefully push your local changes over someone else's work.", "To merge two branches together without creating a merge commit.", "To undo a `git reset --hard`." },
                    0, "`--amend` changes the last commit. It is perfect for fixing typos. However, it changes the commit hash! If you amend a commit that has already been pushed, pushing again will fail unless you forcefully push (which is dangerous).",
                    skillId: 34),
                CreateQuestion(id++, "What does 'squashing' commits mean in Git?",
                    QuestionCategory.Technical, JobTitleRoleFamily.DevOps,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "Compressing the `.git` folder using ZIP to save hard drive space.", "Forcefully deleting commits that contain bugs.", "Automatically rejecting commits that don't pass CI/CD pipeline tests.", "Combining multiple sequential commits into a single, cohesive commit to keep the project history clean and readable before merging." },
                    3, "Squashing cleans up messy history. Instead of pushing 10 commits like 'WIP', 'fix typo', 'oops', you squash them into one meaningful commit ('Implemented login UI'). This is a standard requirement for enterprise Pull Requests.",
                    skillId: 34),
                CreateQuestion(id++, "What is the primary function of `git reflog`?",
                    QuestionCategory.Technical, JobTitleRoleFamily.DevOps,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "It lists all the remote branches available to pull from.", "It records a chronological history of every time the HEAD pointer moved, allowing you to recover 'lost' commits even after a hard reset or branch deletion.", "It generates a detailed PDF report of all code changes for auditing.", "It automatically fixes corrupted Git repositories." },
                    1, "`git reflog` is your safety net. It tracks every movement of HEAD. If you accidentally `git reset --hard` and lose a commit, `reflog` allows you to find its hash and instantly recover it. It makes Git virtually indestructible locally.",
                    skillId: 34),
            });


