            questions.AddRange(new[]
            {
                CreateQuestion(id++, "What is the primary purpose of the `git bisect` command?",
                    QuestionCategory.Technical, JobTitleRoleFamily.DevOps,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "It uses a binary search algorithm to quickly find the exact commit that introduced a bug by repeatedly checking out commits between a 'good' and 'bad' state.", "It splits a large, complex branch into two smaller, more manageable branches.", "It runs two identical git operations in parallel across multiple CPU cores to speed up large fetches.", "It forcefully cuts a merge conflict in half, deleting one side entirely to force resolution." },
                    0, "`git bisect` is an incredible debugging tool. By telling Git a known 'good' commit and a known 'bad' commit, it performs a binary search, checking out the middle commit, asking you to test it, and repeating until it pinpoints the exact commit that broke the code.",
                    skillId: 34),
                CreateQuestion(id++, "If you accidentally committed a massive 1GB database file 50 commits ago and need to completely purge it from the entire repository history to reduce clone size, which tool should you use?",
                    QuestionCategory.Technical, JobTitleRoleFamily.DevOps,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "Use `git rm --cached <file>` and commit the change.", "Use `git filter-repo` (or the deprecated `git filter-branch`) to rewrite the entire repository history, completely destroying the file's historical existence.", "Use `git reset --hard HEAD~50` and then forcefully push.", "Add the file to `.gitignore` and run `git clean -fd`." },
                    1, "Simply deleting a file (`git rm`) does not remove it from Git's history; the repo size remains bloated because Git remembers the file existed. You must use history-rewriting tools like `git filter-repo` to permanently erase the file's blob from all past commits.",
                    skillId: 34),
                CreateQuestion(id++, "In Git's internal storage mechanism, what are the four primary object types?",
                    QuestionCategory.Technical, JobTitleRoleFamily.DevOps,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "Branches, Tags, Stashes, and Remotes.", "Blobs (file contents), Trees (directories), Commits (snapshots), and Tags (annotated references).", "Files, Folders, Hashes, and Pointers.", "Diffs, Patches, Merges, and Revisions." },
                    1, "Git is essentially a simple key-value data store. A 'Blob' stores file data, a 'Tree' stores directory structures, a 'Commit' points to a specific Tree, and an 'Annotated Tag' points to a Commit. Understanding this architecture demystifies complex Git operations.",
                    skillId: 34),
                CreateQuestion(id++, "What is a Git Submodule?",
                    QuestionCategory.Technical, JobTitleRoleFamily.DevOps,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "A feature that allows you to keep another Git repository as a subdirectory of your own repository, tracking a specific commit of that external project.", "A specific type of branch that cannot be merged into the main line of development.", "A hidden folder inside `.git` that caches local file changes before they are formally staged.", "A secondary remote server that acts as a backup for your primary GitHub remote." },
                    0, "Submodules allow you to nest repositories. They are extremely useful for including third-party libraries or shared component repositories. However, they track a specific *commit hash*, not a branch, making them somewhat notoriously difficult to update properly.",
                    skillId: 34),
                CreateQuestion(id++, "Why is `git push --force-with-lease` considered significantly safer than `git push --force`?",
                    QuestionCategory.Technical, JobTitleRoleFamily.DevOps,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "It requires the user to type their password twice to confirm the destructive action.", "It only allows repository administrators (owners) to execute the forced push.", "It creates a backup branch on the remote server before overwriting the history.", "It checks the remote branch first and refuses to overwrite it if someone else has pushed new commits that you haven't fetched yet." },
                    3, "`--force` blindly overwrites the remote branch, instantly destroying a teammate's work if they pushed before you did. `--force-with-lease` safely checks if your local tracking branch matches the remote before pushing. Senior developers use `--force-with-lease` exclusively.",
                    skillId: 34),
            });


