            questions.AddRange(new[]
            {
                CreateQuestion(id++, "Which programming language is exclusively used to write Flutter applications?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Mobile,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "Kotlin", "Swift", "Dart", "Java" },
                    2, "Flutter relies exclusively on Dart, an object-oriented, C-style language developed by Google. Attempting to write Flutter layout code in Java, Swift, or JavaScript is impossible. Dart enables Flutter's fast JIT compilation for Hot Reload and AOT compilation for fast production apps.",
                    skillId: 37),
                CreateQuestion(id++, "What is the fundamental building block of a Flutter user interface?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Mobile,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "An Activity, similar to native Android.", "A Widget. In Flutter, almost everything is a widget, including layout models, animations, and typography.", "An HTML DOM Element.", "A ViewController, similar to native iOS." },
                    1, "The core philosophy of Flutter is 'Everything is a widget'. A Widget is an immutable description of part of a user interface. This contrasts with native development (Activities/Views in Android or UIViews in iOS) and web (DOM).",
                    skillId: 37),
                CreateQuestion(id++, "What is the primary difference between a `StatelessWidget` and a `StatefulWidget`?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Mobile,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "There is no difference; they are just aliases for the same class.", "A `StatelessWidget` is immutable and cannot change its appearance dynamically after it is built, whereas a `StatefulWidget` maintains internal state that can trigger UI rebuilds.", "A `StatelessWidget` is used exclusively for Android, while a `StatefulWidget` is used for iOS.", "A `StatelessWidget` executes much faster but cannot contain text." },
                    1, "A `StatelessWidget` cannot rebuild itself once instantiated (e.g., an Icon or static Text). A `StatefulWidget` holds an internal `State` object that survives UI rebuilds and can trigger redraws via `setState()`. Mixing them up prevents UI interactivity.",
                    skillId: 37),
                CreateQuestion(id++, "What is the purpose of the `pubspec.yaml` file in a Flutter project?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Mobile,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "It defines the database schema for local SQLite storage.", "It is the main entry point where Dart code execution begins.", "It manages project dependencies, assets (like images and fonts), and project configuration metadata.", "It configures the underlying C++ engine parameters for the app." },
                    2, "`pubspec.yaml` is the control center for a Flutter project. It defines package dependencies (from pub.dev), font families, and image asset paths. Failing to declare an image asset in this file results in an invisible image at runtime.",
                    skillId: 37),
                CreateQuestion(id++, "Which function serves as the mandatory entry point for every Flutter application?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Mobile,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "`main()`, which typically calls `runApp()`.", "`startApp()`", "`build()`", "`initState()`" },
                    0, "`void main()` is the entry point. It invariably calls `runApp(const MyApp());` to attach the root widget to the screen. Attempting to start execution from `build()` or `initState()` shows a fundamental misunderstanding of Dart execution flow.",
                    skillId: 37),
                CreateQuestion(id++, "What is the difference between 'Hot Reload' and 'Hot Restart' in Flutter?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Mobile,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "Hot Reload only updates UI colors, while Hot Restart updates logic.", "They are the exact same operation.", "Hot Reload is for Android, while Hot Restart is for iOS.", "Hot Reload injects updated code into the running Dart Virtual Machine while preserving the app's current state. Hot Restart completely destroys the state and rebuilds the app from scratch." },
                    3, "Hot Reload injects updated source code into the Dart Virtual Machine (JIT), instantly updating the UI while keeping variables/state intact. Hot Restart clears all variables and restarts the app. This speed is Flutter's biggest developer experience advantage.",
                    skillId: 37),
                CreateQuestion(id++, "What does the `Scaffold` widget provide?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Mobile,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "A secure sandbox to test experimental Dart code.", "An invisible container that drastically speeds up animations.", "A grid system for arranging photos.", "A basic Material Design visual layout structure, providing APIs for an AppBar, Drawers, BottomNavigationBars, and SnackBar." },
                    3, "`Scaffold` implements the basic Material Design visual layout. It provides a standard app structure (app bar, body, floating action button). Without a Scaffold, adding standard components like a Drawer requires immense manual configuration.",
                    skillId: 37),
                CreateQuestion(id++, "If you only need to enforce specific width and height constraints on a child widget without any decoration, which widget is the most performant choice?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Mobile,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "`Align`", "`Container`", "`SizedBox`", "`Padding`" },
                    2, "`SizedBox` is highly optimized. If you need a 10x10 empty space, using a `Container(width: 10, height: 10)` adds unnecessary overhead because Container checks for decorations, padding, and constraints. `SizedBox` skips all that.",
                    skillId: 37),
                CreateQuestion(id++, "How do the `Column` and `Row` widgets arrange their children?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Mobile,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "Both arrange children dynamically based on screen rotation.", "`Column` arranges children vertically (top-to-bottom), while `Row` arranges them horizontally (left-to-right).", "`Column` arranges children horizontally, while `Row` arranges them vertically.", "`Column` overlaps children on the Z-axis, while `Row` acts as a list." },
                    1, "Rows and Columns form the absolute foundation of Flutter layouts. `Column` aligns children vertically (Y-axis), and `Row` aligns them horizontally (X-axis). Using the wrong one instantly breaks your intended UI design.",
                    skillId: 37),
                CreateQuestion(id++, "What happens when you call `setState()` inside a `StatefulWidget`?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Mobile,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "It navigates the user back to the previous screen.", "It permanently writes the current variables to the local database.", "It forcefully terminates all background threads to save memory.", "It notifies the Flutter framework that the internal state of the object has changed, prompting it to schedule a call to the `build()` method to update the UI." },
                    3, "`setState()` flags the widget's internal state as 'dirty'. During the next frame (usually within 16ms), the framework calls the `build()` method again to reflect the new variable values on the screen. It is the purest form of Reactivity in Flutter.",
                    skillId: 37),
                CreateQuestion(id++, "Unlike React Native, which uses native OEM widgets via a JavaScript bridge, how does Flutter render its UI?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Mobile,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "Flutter runs a hidden web browser and renders the UI using HTML5 Canvas.", "Flutter converts Dart code directly into Swift for iOS and Java for Android.", "Flutter strictly uses native Android XML and iOS Storyboards under the hood.", "Flutter bypasses native UI components entirely and draws every pixel directly to the screen using its own high-performance C++ rendering engine (Skia or Impeller)." },
                    3, "Unlike React Native (which uses a slow bridge to manipulate native OS widgets), Flutter uses its own rendering engine (Skia or the newer Impeller) to paint every pixel directly onto a blank canvas. This provides native-like 60/120fps performance and exact UI consistency across OSs.",
                    skillId: 37),
                CreateQuestion(id++, "What exactly is a `BuildContext` in Flutter?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Mobile,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "A configuration string that defines the app's minimum SDK versions.", "A locator that tracks a widget's exact position within the Widget Tree, essential for theme lookups, navigation, and state access.", "A memory cache that stores images to prevent reloading.", "A background isolate used exclusively for fetching API data." },
                    1, "A `BuildContext` is literally a handle to the location of a widget in the widget tree. If you try to call `Navigator.of(context)` but pass a context from a widget *above* the Navigator, it will crash. Understanding Context is vital for avoiding runtime routing errors.",
                    skillId: 37),
                CreateQuestion(id++, "In Dart, what is the core difference between a `Future` and a `Stream`?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Mobile,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "A `Future` is used for integer math, while a `Stream` is used for video playback.", "A `Future` represents a single asynchronous event that will resolve or fail once, whereas a `Stream` provides a continuous sequence of asynchronous events over time.", "There is no difference; they are interchangeable keywords for network requests.", "A `Future` is strictly synchronous, while a `Stream` is asynchronous." },
                    1, "A `Future` is a value that will be available 'later' (e.g., a single HTTP request). A `Stream` delivers multiple values over time (e.g., Firebase real-time database updates or GPS location streams). Confusing them causes infinite loading or missed data.",
                    skillId: 37),
                CreateQuestion(id++, "What is the difference between `Navigator.push()` and `Navigator.pushReplacement()`?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Mobile,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "`pushReplacement()` animates the transition, while `push()` is instant.", "`push()` adds a new route to the top of the navigation stack, while `pushReplacement()` completely replaces the current route, preventing the user from returning to it via the back button.", "`push()` clears the entire stack, while `pushReplacement()` only clears the top.", "`push()` is used for popups, while `pushReplacement()` is used for full screens." },
                    1, "`pushReplacement` pops the top route off the stack and pushes the new one, effectively replacing it. This is mandatory for things like Login screens—you don't want the user hitting the Android 'Back' button and returning to the Login page after authenticating.",
                    skillId: 37),
                CreateQuestion(id++, "In the `StatefulWidget` lifecycle, what is unique about `initState()` compared to `build()`?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Mobile,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "`initState()` is used to draw the UI, while `build()` handles API requests.", "`initState()` cannot access local variables, but `build()` can.", "`build()` is asynchronous, while `initState()` is strictly synchronous.", "`initState()` is called exactly once when the state object is inserted into the tree, whereas `build()` can be called dozens of times per second (e.g., during animations)." },
                    3, "`initState()` runs exactly once when the widget is born. `build()` runs constantly. Putting a heavy API request directly inside `build()` will cause a DDoS attack on your server because Flutter will fire the request every time a micro-animation triggers a rebuild.",
                    skillId: 37),
                CreateQuestion(id++, "Why would you use a `GlobalKey` instead of a `ValueKey` in Flutter?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Mobile,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "A `GlobalKey` allows a widget to maintain its state when moved entirely across the widget tree, and allows external code to access its state directly.", "A `GlobalKey` automatically encrypts its data.", "You should never use a `GlobalKey` because it immediately causes memory leaks.", "A `ValueKey` can only be a string, while a `GlobalKey` must be an integer." },
                    0, "`GlobalKey` provides an identity across the entire app. It is costly but necessary when a widget (like a complex Map or Video Player) must move to a completely different part of the widget tree without losing its internal state or rebuilding.",
                    skillId: 37),
                CreateQuestion(id++, "When using `ListView`, what is the critical performance advantage of using `ListView.builder` over a standard `ListView(children: [...])`?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Mobile,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "`ListView.builder` forces the list to scroll horizontally instead of vertically.", "`ListView.builder` automatically sorts items alphabetically.", "`ListView.builder` prevents the user from over-scrolling.", "`ListView.builder` creates items lazily as they scroll onto the screen, drastically reducing memory usage and initialization time for long or infinite lists." },
                    3, "A standard `ListView` renders all children instantly, causing massive memory spikes and UI lag if the list has 1,000 items. `ListView.builder` only renders the 5-10 items currently visible on the screen, recycling them as you scroll, guaranteeing 60fps.",
                    skillId: 37),
                CreateQuestion(id++, "Inside a `Row` or `Column`, what is the difference between the `Expanded` and `Flexible` widgets?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Mobile,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "`Flexible` automatically wraps text, while `Expanded` cuts it off.", "`Expanded` forces the child to fill all available remaining space (tight constraint), whereas `Flexible` allows the child to shrink to its own size if it wants, while only preventing it from overflowing.", "There is no difference; `Expanded` is just deprecated.", "`Expanded` can only be used in Rows, while `Flexible` is exclusively for Columns." },
                    1, "`Expanded` uses `FlexFit.tight` (forcing the child to fill the space). `Flexible` uses `FlexFit.loose` (allowing the child to be smaller than the space). Understanding Flex behaviors prevents the dreaded 'RenderFlex overflowed by X pixels' yellow-tape error.",
                    skillId: 37),
                CreateQuestion(id++, "What does a `FutureBuilder` widget do?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Mobile,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "It automatically generates Dart classes from JSON data.", "It pre-caches images from the internet in the background.", "It builds itself based on the latest snapshot of interaction with a Dart `Future`, allowing developers to easily show loading spinners, error messages, and success data states automatically.", "It compiles the app 'in the future' using ahead-of-time (AOT) compilation." },
                    2, "`FutureBuilder` automatically subscribes to a Future. It provides a `snapshot` object that tells you if the Future is loading, has data, or threw an error. It cleanly isolates async state management from the main UI code without needing complex `setState` logic.",
                    skillId: 37),
                CreateQuestion(id++, "If you need to access data from a deeply nested child widget without passing callbacks through 10 intermediate constructors, what core Flutter mechanism makes this possible?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Mobile,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "It is impossible; Flutter strictly requires constructor prop-drilling for all data.", "A `ListView`.", "An `InheritedWidget` (which powers `Theme.of(context)`, `MediaQuery`, and state management tools like `Provider`).", "A `SizedBox`." },
                    2, "`InheritedWidget` sits at the top of a tree and allows deep descendants to access its data in O(1) time without prop-drilling via constructors. State management frameworks like Provider and BLoC are essentially elegant wrappers around `InheritedWidget`.",
                    skillId: 37),
                CreateQuestion(id++, "Dart is fundamentally single-threaded. How does Flutter perform heavy background processing (like parsing huge JSON files) without dropping frames and freezing the UI?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Mobile,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "By delegating the task directly to the Swift/Kotlin native layer via Method Channels.", "By using a `StreamController` to buffer the data.", "By spawning an `Isolate` (via `Isolate.spawn` or `compute()`), which creates an entirely separate memory heap and thread that communicates with the main thread via message passing.", "By wrapping the heavy function in an `async` block and using `await`." },
                    2, "Dart's main thread runs the UI. If you parse a 50MB JSON file there, the Event Loop blocks and the UI completely freezes. `Isolate.spawn` or `compute()` spins up an OS thread with its own isolated memory, allowing heavy math without dropping frames.",
                    skillId: 37),
                CreateQuestion(id++, "Flutter maintains three separate trees to render the UI. What are they?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Mobile,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "The Dart Tree, the C++ Tree, and the Skia Tree.", "The State Tree, the Props Tree, and the DOM Tree.", "The Logic Tree, the Visual Tree, and the GPU Tree.", "The Widget Tree (configuration), the Element Tree (lifecycle/instantiation), and the RenderObject Tree (layout/painting)." },
                    3, "Widgets are lightweight blueprints (Configuration). Elements represent the actual widget instantiated in the tree (Lifecycle). RenderObjects perform the heavy lifting of sizing, layout, and painting the pixels. Senior developers debug performance by understanding RenderObjects.",
                    skillId: 37),
                CreateQuestion(id++, "Why does the Flutter linter aggressively warn you to 'Use const with the constructor to improve performance'?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Mobile,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "Using `const` encrypts the widget's internal data.", "Using `const` allows the widget to access global variables instantly.", "A `const` widget is instantiated strictly at compile-time. During a UI rebuild (e.g., `setState`), Flutter entirely skips rebuilding `const` widgets, saving massive amounts of CPU cycles.", "It is purely stylistic to make code readable; there is zero runtime performance difference." },
                    2, "`const` widgets are evaluated at compile-time. When a parent widget rebuilds, Flutter does an object-identity check. If it sees a `const` widget, it knows unequivocally that the widget hasn't changed and entirely skips rebuilding it, drastically reducing CPU load.",
                    skillId: 37),
                CreateQuestion(id++, "What dangerous scenario occurs if you try to use `Navigator.of(context).pop()` after an asynchronous `await` gap in a StatefulWidget, and how do you prevent it?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Mobile,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "The Dart VM will crash. You must restart the app.", "The user might have already navigated away, causing the widget to be unmounted and throwing an exception. You must check `if (!mounted) return;` before using the context.", "The API response will be null. You must wrap it in a `try/catch` block.", "The app will trigger an infinite loop. You must use `Navigator.pushReplacement()` instead." },
                    1, "Asynchronous gaps (`await`) release the main thread. While waiting for a 5-second API call, the user might hit 'Back' and destroy the widget. If the code resumes and calls `Navigator.pop(context)`, the app crashes because the context is dead. `if (!mounted) return;` prevents this.",
                    skillId: 37),
                CreateQuestion(id++, "In a StatefulWidget, what is the exact difference between `didChangeDependencies()` and `didUpdateWidget()`?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Mobile,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "`didChangeDependencies()` only works for iOS, while `didUpdateWidget()` only works for Android.", "`didChangeDependencies()` is called when an `InheritedWidget` this widget relies on changes, while `didUpdateWidget()` is called when the parent widget rebuilds and provides new constructor arguments.", "`didChangeDependencies()` is called when the network disconnects, while `didUpdateWidget()` is called when the screen rotates.", "They are synonymous and called simultaneously during `setState()`." },
                    1, "`didChangeDependencies` triggers when an `InheritedWidget` above it changes (e.g., Theme/Locale swaps). `didUpdateWidget` triggers when the *parent* rebuilds and passes a new object to the constructor. Misusing these causes infinite loops or stale data.",
                    skillId: 37),
                CreateQuestion(id++, "What happens if you fail to call `dispose()` on controllers (like `TextEditingController`, `AnimationController`, or `ScrollController`) in a StatefulWidget?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Mobile,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "The text fields will automatically clear their text upon navigation.", "The app will fail to compile in release mode.", "The Flutter garbage collector automatically cleans them up after 60 seconds anyway.", "The native resources and event listeners attached to the controllers remain active even after the widget is destroyed, causing a massive memory leak that will eventually crash the app." },
                    3, "Controllers attach native listeners to the OS (like keyboard tracking or scrolling). If you navigate away and destroy the widget without calling `controller.dispose()` in the `dispose()` override, those listeners live forever in RAM, causing catastrophic memory leaks.",
                    skillId: 37),
                CreateQuestion(id++, "When implementing complex, highly custom 2D drawings (like a dynamic line chart or a drawing pad) in Flutter, which widget is the correct architectural choice?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Mobile,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "`BackdropFilter` combined with `Opacity`.", "A `Stack` of thousands of 1x1 pixel `Container` widgets.", "An `Image` widget connected to a remote server.", "`CustomPaint` along with a class that extends `CustomPainter`, which allows direct low-level drawing commands onto a canvas." },
                    3, "For massive amounts of custom drawing (like rendering a sine wave or a physics engine), using a `Stack` with standard widgets causes immense RenderObject overhead. `CustomPainter` talks almost directly to the Skia engine, allowing highly optimized, low-level canvas painting.",
                    skillId: 37),
                CreateQuestion(id++, "What is a Flutter 'MethodChannel' used for?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Mobile,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "It allows Flutter apps to bypass the Google Play Store for updates.", "It is a state management library heavily reliant on streams.", "It provides an asynchronous message-passing bridge allowing Dart code to call native Swift/Objective-C methods on iOS and Kotlin/Java methods on Android.", "It is the network layer used exclusively to make REST API calls over HTTP." },
                    2, "Flutter cannot directly access native APIs like Bluetooth, ARKit, or Battery Level. A `MethodChannel` serializes Dart messages, sends them across the C++ engine to the native host (Swift/Kotlin), executes the native code, and passes the result back asynchronously.",
                    skillId: 37),
                CreateQuestion(id++, "What is the role of a `TickerProvider` (like `SingleTickerProviderStateMixin`) when working with Animations?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Mobile,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "It tracks the user's keystrokes to detect idle timeouts.", "It measures the network latency for video streaming.", "It creates a `Ticker` that 'ticks' precisely in sync with the screen's refresh rate (typically 60 or 120 times per second), driving the `AnimationController` smoothly without wasting CPU.", "It generates a random seed number for cryptographic functions." },
                    2, "Animations require updating a value 60 times a second. A `TickerProvider` hooks directly into the OS's display refresh rate (Vsync). Without it, an animation might run on a blind `setInterval` loop, causing screen-tearing and destroying battery life.",
                    skillId: 37),
                CreateQuestion(id++, "In the context of Flutter's build modes, what does AOT compilation refer to, and when is it used?",
                    QuestionCategory.Technical, JobTitleRoleFamily.Mobile,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "AOT compiles code instantly as you type, powering the Hot Reload feature during Debug mode.", "AOT (Ahead-of-Time) compilation translates Dart code into native ARM machine code *before* the app is distributed, drastically improving startup time and performance in Release mode.", "AOT converts Dart into JavaScript to run Flutter apps strictly inside Chrome.", "AOT automatically analyzes code for unused variables and removes them." },
                    1, "JIT (Just-In-Time) compilation powers debug mode (enabling Hot Reload by compiling on the fly). AOT (Ahead-Of-Time) compilation translates Dart to native ARM binary before release. AOT is why production Flutter apps start in milliseconds and run flawlessly at 120fps.",
                    skillId: 37),
            });


            // ═══════════════════════════════════════════════════════════════════════════════
            // SOFT SKILLS EXPANSION (Problem Solving, Communication, Project Mgmt, Agile)
            // ═══════════════════════════════════════════════════════════════════════════════

            questions.AddRange(new[]
            {
                CreateQuestion(id++, "You are debugging a production issue but cannot reproduce it locally. What is the most effective first step?",
                    QuestionCategory.SoftSkill, JobTitleRoleFamily.Other,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "Analyze production logs and monitoring data to gather as much context as possible before touching any code.", "Add debug print statements and redeploy to production.", "Ask a teammate to reproduce it on their machine.", "Immediately roll back the last deployment." },
                    0, "Debugging non-reproducible issues requires evidence first. Production logs, error traces, and metrics provide the 'what happened' context without the risk of blind code changes. Jumping to rollbacks or code changes without understanding the problem often hides symptoms rather than fixing root causes.",
                    skillId: 47),
                CreateQuestion(id++, "When faced with a completely unfamiliar technical problem, which approach leads to the most effective solution?",
                    QuestionCategory.SoftSkill, JobTitleRoleFamily.Other,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "Search Stack Overflow until you find a code snippet that looks similar and copy it.", "Ask someone else to solve it for you.", "Try random solutions until something works.", "Break the problem into smaller pieces, research each part separately, form a hypothesis, and test it systematically." },
                    3, "Systematic decomposition and hypothesis-testing is the scientific method applied to engineering. Copying code blindly is risky because context matters. Structured problem-solving builds expertise and leads to genuinely understood solutions.",
                    skillId: 47),
                CreateQuestion(id++, "A feature you developed is working correctly, but the performance is unacceptably slow. What should you do first?",
                    QuestionCategory.SoftSkill, JobTitleRoleFamily.Other,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "Rewrite the entire feature using a different approach.", "Optimize the parts that look slowest in the code by eye.", "Profile the code to identify the actual bottleneck before making any optimization changes.", "Add more hardware resources to compensate." },
                    2, "Premature optimization is the root of much wasted engineering time. Profiling first gives you data on where the actual bottleneck is. Rewriting entire features and guessing at optimizations are expensive gambles that often do not improve the real bottleneck at all.",
                    skillId: 47),
                CreateQuestion(id++, "Two equally valid technical solutions exist for a problem. How do you decide which to implement?",
                    QuestionCategory.SoftSkill, JobTitleRoleFamily.Other,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "Pick the more technically complex solution to demonstrate skill.", "Ask your manager to decide, since it is their responsibility.", "Evaluate them against concrete criteria: maintainability, performance needs, team expertise, and long-term cost.", "Pick whichever is quicker to implement right now." },
                    2, "The best technical decision is contextual. Rushing to the fastest implementation creates tech debt; over-engineering wastes resources. Evaluating trade-offs against measurable criteria ensures the chosen solution serves the project's real constraints and goals.",
                    skillId: 47),
                CreateQuestion(id++, "A critical system is experiencing intermittent failures with no obvious pattern. What is the most rigorous approach to identify the root cause?",
                    QuestionCategory.SoftSkill, JobTitleRoleFamily.Other,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "Increase system resources and observe whether failures stop.", "Fix the most recently changed code since it is most likely the cause.", "Wait for the issue to become consistent before investigating.", "Correlate all available signals (timestamps, server metrics, deployment history, error rates) to find common variables across failure events." },
                    3, "Intermittent issues are the hardest engineering problems. Correlation across multiple data dimensions is the key to identifying root causes. Waiting for consistency means unacceptable downtime, and blaming recent changes without data is a guess that wastes time.",
                    skillId: 47),
                CreateQuestion(id++, "Your team has identified three potential root causes for a recurring production bug but can only fix one before the next release. How do you prioritize?",
                    QuestionCategory.SoftSkill, JobTitleRoleFamily.Other,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "Delay the release until all three are investigated fully.", "Fix all three quickly with minimal testing to be safe.", "Fix the easiest one and close the ticket.", "Quantify the impact and likelihood of each root cause, fix the one with the highest expected value, and document the others with risk assessment in the backlog." },
                    3, "Resource-constrained prioritization is a core senior engineering skill. Expected value (impact multiplied by likelihood) guides rational decisions. Documenting the deferred risks ensures nothing is forgotten, and rushing all three without testing introduces more bugs than it fixes.",
                    skillId: 47),
                CreateQuestion(id++, "A non-technical stakeholder asks how long a feature will take. You are still uncertain. What is the best response?",
                    QuestionCategory.SoftSkill, JobTitleRoleFamily.Other,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "Tell them it depends on too many factors and leave it at that.", "Say you cannot give an estimate until every detail is defined.", "Provide a rough range with clear assumptions, explain what could change the estimate, and commit to a more precise timeline after a short investigation.", "Give a specific number to appear confident, even if you are unsure." },
                    2, "Honest communication under uncertainty builds trust more than false precision or refusal to engage. A range with explicit assumptions respects the stakeholder's planning needs while managing expectations. Stakeholders need something to plan around even when details are unclear.",
                    skillId: 48),
                CreateQuestion(id++, "During a code review, you believe your reviewer is incorrect about a suggested change. What is the most professional way to respond?",
                    QuestionCategory.SoftSkill, JobTitleRoleFamily.Other,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "Ignore their comment and merge as-is.", "Accept all comments immediately without discussion to avoid conflict.", "Escalate to a manager immediately.", "Politely explain your reasoning with a concrete example or reference, acknowledge any merit in their feedback, and propose discussing it further if needed." },
                    3, "Respectful technical disagreement is healthy and necessary for quality code reviews. Providing evidence-based reasoning opens a productive dialogue where either party may learn something. Simply ignoring or blindly accepting feedback both lead to worse code quality.",
                    skillId: 48),
                CreateQuestion(id++, "You discover that a feature requested by a client would incur significant hidden complexity and maintenance costs. What should you do?",
                    QuestionCategory.SoftSkill, JobTitleRoleFamily.Other,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "Just build it as requested without raising concerns.", "Add a comment in the code and build it anyway.", "Refuse to build it without explaining why.", "Proactively communicate the trade-offs to the client with clear examples, propose simpler alternatives, and let them make an informed decision." },
                    3, "Clients make better decisions when engineers surface hidden complexity proactively. Engineers who only say yes and hide complexity accumulate technical debt silently, eroding trust and project health. Proposing alternatives treats clients as intelligent partners.",
                    skillId: 48),
                CreateQuestion(id++, "You are presenting a complex architectural decision to both technical and non-technical leadership. How do you structure the presentation?",
                    QuestionCategory.SoftSkill, JobTitleRoleFamily.Other,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "Lead with the business impact and recommendation, then provide technical details for those who want them, tailoring depth to each audience.", "Present all technical details first so everyone fully understands the implementation.", "Send a technical document and skip the presentation entirely.", "Keep everything at a high level and avoid all technical content to prevent confusion." },
                    0, "Effective communication to mixed audiences starts with what everyone cares about (the outcome and recommendation) and provides depth progressively. Technical leaders want implementation details; business leaders need the business impact. Forcing either audience through the wrong level of detail causes confusion and lost buy-in.",
                    skillId: 48),
                CreateQuestion(id++, "Your team is about to miss a sprint commitment. When should you communicate this to stakeholders?",
                    QuestionCategory.SoftSkill, JobTitleRoleFamily.Other,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "At the end of the sprint when the missed work is obvious.", "Only if asked directly by a stakeholder.", "After the sprint retro, when you have had time to analyze the cause.", "As soon as the risk becomes apparent, with a clear explanation of the current state and a revised plan." },
                    3, "Early escalation of risks is a hallmark of professional teams. Delaying bad news until the last moment removes the stakeholder's ability to adjust plans or provide resources. Transparency early, even when uncomfortable, builds lasting trust and gives everyone maximum time to respond.",
                    skillId: 48),
                CreateQuestion(id++, "A colleague repeatedly interrupts others in meetings, preventing balanced participation. You are facilitating. How do you handle it?",
                    QuestionCategory.SoftSkill, JobTitleRoleFamily.Other,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "Cancel the meeting and address it separately.", "Use structured facilitation techniques to redirect diplomatically without embarrassing anyone, ensuring all voices are heard.", "Ignore it and let the meeting proceed naturally.", "Call the person out publicly and firmly." },
                    1, "Meeting facilitation requires maintaining psychological safety while ensuring all voices are heard. Public call-outs create defensiveness; ignoring the behavior excludes quieter voices. Structured redirection is a neutral, professional technique that improves meeting quality without targeting individuals.",
                    skillId: 48),
                CreateQuestion(id++, "You need to advocate for a significant engineering investment to non-technical executives who control the budget. What is most effective?",
                    QuestionCategory.SoftSkill, JobTitleRoleFamily.Other,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "Argue that it is the industry best practice and every top company does it.", "Frame the investment in business terms: quantify current costs, risks, and return on investment, with a clear implementation roadmap.", "Show executives the technical documentation and architecture diagrams.", "Request the budget without justification and trust that engineers know best." },
                    1, "Executives make decisions based on business outcomes, not technical elegance. Translating engineering needs into business language (cost avoidance, revenue risk, productivity gains) is a critical senior skill. Industry best practice arguments rarely secure budget approval without corresponding financial justification.",
                    skillId: 48),
                CreateQuestion(id++, "Two senior engineers on your team have a strong ongoing technical disagreement that is blocking progress. How do you resolve it?",
                    QuestionCategory.SoftSkill, JobTitleRoleFamily.Other,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "Let them argue until one gives up.", "Facilitate a structured discussion: define decision criteria together, evaluate each approach against those criteria, and use data or a small prototype to break the deadlock.", "Randomly choose one approach to unblock the team.", "Escalate immediately to a director to make the call." },
                    1, "Strong technical disagreements between senior engineers are healthy but must be resolved productively. Moving from 'who is right' to 'what is best given our constraints' removes ego from the decision. A criteria-driven process builds team alignment and produces a defensible outcome everyone can commit to.",
                    skillId: 48),
                CreateQuestion(id++, "A new task is added mid-sprint that the Product Owner considers urgent. What is the correct process in Scrum?",
                    QuestionCategory.SoftSkill, JobTitleRoleFamily.Other,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "Reject it entirely since the sprint is already committed.", "Work overtime to fit it in without adjusting scope.", "Discuss the impact with the Product Owner and the team, then negotiate to either remove equivalent scope or accept that the sprint goal will be affected.", "Immediately add it to the sprint without discussion." },
                    2, "Scrum sprints are commitments to a goal, not a locked contract. The team must actively negotiate scope changes to protect sprint integrity and predictability. Simply adding work without discussion undermines the sprint goal; transparent conversation about trade-offs is exactly what Scrum facilitates.",
                    skillId: 49),
                CreateQuestion(id++, "A project is at 90% completion but has been stalled for two weeks. What is most likely happening and how should you respond?",
                    QuestionCategory.SoftSkill, JobTitleRoleFamily.Other,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "Extend the timeline indefinitely until it is truly complete.", "Add more developers to the project immediately.", "The project is likely suffering from the 90% complete trap. Identify and explicitly track the remaining tasks, dependencies, and blockers.", "Declare it done and ship it." },
                    2, "The 90% trap is a well-known project management anti-pattern where the last 10% takes disproportionate time due to integration issues, edge cases, and testing. Stalling is a signal to decompose the remaining work explicitly. Adding resources at this stage often slows progress further by introducing coordination overhead.",
                    skillId: 49),
                CreateQuestion(id++, "You are leading a project when two key engineers unexpectedly go on extended leave. How do you manage this?",
                    QuestionCategory.SoftSkill, JobTitleRoleFamily.Other,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "Put the project on hold until the engineers return.", "Immediately reassess the scope and timeline, communicate the impact transparently to stakeholders, adjust the plan based on remaining capacity, and document critical knowledge.", "Promise stakeholders the same timeline and figure out the rest later.", "Reassign their work to remaining team members without adjusting timelines." },
                    1, "Unexpected resource changes require immediate, transparent communication. Promising impossible timelines creates false confidence and later destroys trust. A realistic adjusted plan, even with a later date, is far more valuable than an ambitious plan that will be missed. Knowledge documentation prevents critical dependencies on absent individuals.",
                    skillId: 49),
                CreateQuestion(id++, "Stakeholders keep requesting features outside the originally agreed scope and the team is struggling to keep up. How do you address this systematically?",
                    QuestionCategory.SoftSkill, JobTitleRoleFamily.Other,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "Implement a formal change control process: document new requests, evaluate their impact on timeline and resources, and require sign-off before any scope change is accepted.", "Accept all requests to keep stakeholders happy and work overtime.", "Refuse all new requests until the project is delivered.", "Secretly deprioritize existing features to accommodate new requests." },
                    0, "Scope creep is one of the most common causes of project failure. A change control process makes the cost of change visible and requires stakeholders to consciously trade off new requests against existing commitments. Accepting everything destroys team predictability; refusing everything damages relationships. The process is the professional middle ground.",
                    skillId: 49),
                CreateQuestion(id++, "You are managing a project with external vendor dependencies on the critical path. The vendor is consistently late. What is the most effective mitigation strategy?",
                    QuestionCategory.SoftSkill, JobTitleRoleFamily.Other,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "Establish clear milestones with the vendor, escalate professionally when milestones are missed, and create contingency work packages your team can pursue in parallel.", "Wait for the vendor to deliver and adjust timelines accordingly.", "Report the vendor to leadership and let them resolve it.", "Take over the vendor's work with your own team immediately." },
                    0, "External dependencies on the critical path represent the highest project risk. Waiting passively accepts delays; taking over vendor work may not be feasible or contractually allowed. The professional approach combines escalation, contractual accountability, and parallel contingency planning to maintain project momentum regardless of vendor performance.",
                    skillId: 49),
                CreateQuestion(id++, "What is the primary purpose of the Daily Standup (Daily Scrum) in Scrum?",
                    QuestionCategory.SoftSkill, JobTitleRoleFamily.Other,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "To plan the detailed tasks for the day.", "To replace all other team communication during the sprint.", "To synchronize the team, surface blockers, and inspect progress toward the Sprint Goal, not to give status reports to management.", "To give each developer a chance to report their progress to the Scrum Master." },
                    2, "The Daily Scrum is a team-to-team synchronization event, not a status meeting for management. Turning it into a reporting ceremony adds bureaucracy and reduces psychological safety. The three questions exist to improve team collaboration and identify blockers, not to track individual performance.",
                    skillId: 45),
                CreateQuestion(id++, "What is the Definition of Done in Scrum and why is it important?",
                    QuestionCategory.SoftSkill, JobTitleRoleFamily.Other,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "It means the developer believes the feature is finished.", "A shared, explicit agreement of what conditions a product increment must meet before it is considered complete, ensuring consistent quality and reliable velocity.", "It means the Product Owner has signed off on the feature.", "It means the feature has been deployed to production." },
                    1, "The Definition of Done is one of Scrum's most powerful quality tools. Without it, done means different things to different people: code written but not tested, tested but not reviewed, reviewed but not deployed. A clear DoD eliminates hidden work and makes velocity measurements trustworthy across sprints.",
                    skillId: 45),
                CreateQuestion(id++, "Your team's sprint velocity is highly inconsistent from sprint to sprint. What is the most likely cause and how should it be addressed?",
                    QuestionCategory.SoftSkill, JobTitleRoleFamily.Other,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "Inconsistent velocity usually indicates unclear story sizing or frequent scope changes. Address it by improving estimation practices and reducing mid-sprint interruptions.", "It means the team is not working hard enough and should increase capacity.", "Velocity is naturally random and should not be used for planning.", "It means the team is too large and should be split." },
                    0, "Consistent velocity is a sign of a mature, predictable team. Inconsistency is diagnostic information, not a morale problem. Common causes include poor story decomposition, constant context-switching, and unplanned work eating into sprint capacity. Retrospecting on root causes is more effective than adding pressure to work harder.",
                    skillId: 45),
                CreateQuestion(id++, "A senior stakeholder wants detailed daily progress reports from each developer during an Agile project. How do you handle this?",
                    QuestionCategory.SoftSkill, JobTitleRoleFamily.Other,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "Comply and have each developer submit daily reports.", "Educate the stakeholder on Agile transparency mechanisms such as demos and burndown charts, invite them to relevant ceremonies, and explain that individual micro-reporting undermines team autonomy.", "Tell the stakeholder that Agile projects do not require accountability.", "Ignore the request since Agile does not support that level of reporting." },
                    1, "This is a classic tension between traditional management expectations and Agile values. The correct response acknowledges the stakeholder's legitimate need for visibility while explaining that individual micro-management undermines the self-organization that makes Agile effective. Redirecting to Agile ceremonies satisfies the visibility need without regressing to command-and-control patterns.",
                    skillId: 45),
            });


            // ═══════════════════════════════════════════════════════════════════════════════
            // FULLSTACK
            // ═══════════════════════════════════════════════════════════════════════════════

            questions.AddRange(new[]
            {
                CreateQuestion(id++, "What is the fundamental advantage of a full-stack developer over a specialist?",
                    QuestionCategory.Technical, JobTitleRoleFamily.FullStack,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "A full-stack developer can work across the entire technology stack (frontend, backend, database), enabling them to build complete features independently and bridge communication gaps between teams.", "Full-stack developers always have deeper expertise in every technology than specialists.", "Full-stack developers only work on projects that use JavaScript for both frontend and backend.", "Full-stack developers write faster code than specialists in every domain." },
                    0, "Full-stack developers provide breadth, not necessarily depth in every area. Their core value is the ability to own a feature end-to-end, reducing handoffs and communication overhead between specialized teams. However, specialists typically have deeper expertise in their domain. Both roles are valuable depending on team structure.",
                    skillId: 43),
                CreateQuestion(id++, "In a full-stack web application, what is the primary responsibility of the backend compared to the frontend?",
                    QuestionCategory.Technical, JobTitleRoleFamily.FullStack,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "The backend handles styling and animations; the frontend handles database queries.", "The backend handles business logic, data persistence, authentication, and API exposure; the frontend handles user interface rendering and user interaction.", "The backend is only responsible for serving static HTML files to the browser.", "There is no difference — both layers perform identical functions." },
                    1, "Understanding the separation of concerns between frontend and backend is foundational for full-stack development. The backend enforces security, data integrity, and business rules; the frontend focuses on user experience. Blurring this boundary leads to insecure applications (business logic in the browser) or poor user experience (everything server-rendered).",
                    skillId: 43),
                CreateQuestion(id++, "What does CORS stand for, and when does it become relevant in a full-stack application?",
                    QuestionCategory.Technical, JobTitleRoleFamily.FullStack,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "Cross-Origin Resource Sharing. It becomes relevant when a frontend running on one domain (e.g., localhost:3000) tries to make API requests to a backend on a different domain (e.g., localhost:5000).", "Centralized Object Routing System. It applies when deploying applications to the cloud.", "Client-Only Resource Sharing. It is relevant when two databases need to share data.", "Cross-Origin Resource Sharing. It only applies to mobile applications, not web apps." },
                    0, "CORS is enforced by browsers as a security policy. When a frontend at domain A makes a request to an API at domain B, the browser blocks it unless the API explicitly allows it via CORS headers. Full-stack developers must configure this correctly in the backend, as it is one of the most common pain points during initial development setup.",
                    skillId: 43),
                CreateQuestion(id++, "In a typical full-stack application, what is the role of environment variables?",
                    QuestionCategory.Technical, JobTitleRoleFamily.FullStack,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "To store sensitive configuration values (API keys, database connection strings, secrets) outside of the codebase so they are not accidentally committed to version control.", "To configure the CSS theme of the frontend application.", "To define the programming language versions used by the project.", "To store user session data between requests." },
                    0, "Hardcoding secrets in source code is a critical security vulnerability. Environment variables allow the same codebase to run in development, staging, and production with different configurations. A .env file should always be in .gitignore. This practice is required by the Twelve-Factor App methodology and is essential full-stack hygiene.",
                    skillId: 43),
                CreateQuestion(id++, "What is the purpose of a REST API in a full-stack application?",
                    QuestionCategory.Technical, JobTitleRoleFamily.FullStack,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "To store and serve static assets like images and CSS files.", "To provide a standardized, stateless HTTP interface between the frontend and backend, enabling them to be developed, deployed, and scaled independently.", "To directly connect the browser to the database without any intermediate layer.", "To render HTML pages on the server and send them to the client." },
                    1, "A REST API decouples the frontend from the backend. This means the frontend (React, Vue, mobile app) can be replaced or updated independently from the backend, and vice versa. It also enables multiple clients (web, mobile, third-party) to consume the same API, which is why API-first design is the dominant full-stack architecture.",
                    skillId: 43),
                CreateQuestion(id++, "What is the difference between server-side rendering (SSR) and client-side rendering (CSR) in a full-stack context?",
                    QuestionCategory.Technical, JobTitleRoleFamily.FullStack,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "There is no practical difference between SSR and CSR in modern applications.", "SSR generates HTML on the server per request for better SEO and initial load performance; CSR sends a minimal HTML shell and renders the page in the browser using JavaScript.", "CSR is used for APIs and SSR is used only for static websites.", "SSR is faster for all use cases and should always be preferred over CSR." },
                    1, "SSR (used in Next.js, Razor Pages) sends ready-to-display HTML from the server, which is great for SEO and first-contentful-paint. CSR (React SPA) downloads JavaScript and renders in the browser, trading initial load time for a richer interactive experience. Full-stack developers must choose the right model based on the application's SEO and performance needs.",
                    skillId: 43),
                CreateQuestion(id++, "In a full-stack app, why should you never trust data sent from the client (browser) without validating it on the server?",
                    QuestionCategory.Technical, JobTitleRoleFamily.FullStack,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "Because the browser automatically encrypts all data before sending it, making frontend validation redundant.", "Because frontend validation is too slow and always runs after the server receives the request.", "Because server-side validation only applies to mobile applications, not web browsers.", "Because any user can manipulate client-side code or use tools like Postman to send arbitrary data, bypassing all frontend validation." },
                    3, "Frontend validation is a UX convenience, not a security measure. Any user can open browser dev tools, disable JavaScript, or use HTTP clients like Postman or curl to bypass it entirely. Server-side validation is the only reliable defense. Skipping it leads to SQL injection, mass assignment vulnerabilities, and corrupt data.",
                    skillId: 43),
                CreateQuestion(id++, "What is the purpose of a database migration in a full-stack application?",
                    QuestionCategory.Technical, JobTitleRoleFamily.FullStack,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "To move all database data from one country to another for compliance reasons.", "To programmatically version-control the database schema so that all environments (local, staging, production) stay in sync as the application evolves.", "To convert the database from one vendor to another without data loss.", "To automatically back up the database every time the application starts." },
                    1, "Migrations are the database equivalent of Git commits. Without them, databases across environments diverge and deployments break. Tools like EF Core Migrations, Flyway, and Alembic allow the schema to evolve alongside code, so that a developer cloning the repo can reproduce the exact same database state by running a single command.",
                    skillId: 43),
                CreateQuestion(id++, "What does it mean for an API to be stateless, and why does this matter for scalability?",
                    QuestionCategory.Technical, JobTitleRoleFamily.FullStack,
                    QuestionDifficulty.Easy, ExperienceSeniorityLevel.Junior,
                    new[] { "Stateless means the server never stores any data permanently, even in a database.", "Stateless means each request contains all the information needed to process it, with no server-side session memory — enabling any server instance to handle any request, which makes horizontal scaling trivial.", "Stateless means the API can only be used by one client at a time.", "Stateless means the API only returns empty responses with no body content." },
                    1, "Statelessness is a core REST constraint. When servers hold session state, a user must always hit the same server, requiring sticky sessions and preventing true horizontal scaling. Stateless APIs allow any load balancer to route any request to any server instance, which is why JWT (a self-contained token) is preferred over server-side sessions in modern full-stack applications.",
                    skillId: 43),
                CreateQuestion(id++, "A full-stack feature requires showing real-time data updates (e.g., live notifications) to the user. Which technology is most appropriate and why?",
                    QuestionCategory.Technical, JobTitleRoleFamily.FullStack,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "Server-Sent Events are never an option because they are not supported by modern browsers.", "Standard REST API calls on a 100ms interval, because REST is always sufficient.", "WebSockets, because they provide a persistent, bidirectional connection allowing the server to push updates to the client without repeated polling.", "GraphQL, because it has built-in real-time support in all implementations." },
                    2, "Polling with REST wastes resources and adds latency. WebSockets are the standard for bidirectional real-time communication (chat, live dashboards, collaborative editing). Server-Sent Events (SSE) are a simpler alternative for one-directional server-to-client pushes (notifications, live feeds). Full-stack developers must choose the right real-time strategy for their use case.",
                    skillId: 43),
                CreateQuestion(id++, "In a full-stack application, what is the N+1 query problem and how do you solve it?",
                    QuestionCategory.Technical, JobTitleRoleFamily.FullStack,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "The N+1 problem only affects NoSQL databases and does not apply to relational databases.", "The N+1 problem means your API returns one extra item in every list response, which is fixed by adjusting pagination settings.", "The N+1 problem occurs when loading a list of N records triggers N additional queries (one per record). It is solved with eager loading (JOIN queries) or data loader batching.", "The N+1 problem is a JavaScript memory leak caused by creating N+1 event listeners in a loop." },
                    2, "The N+1 problem is one of the most common performance killers in full-stack apps. Fetching 100 posts and then running a separate query per post for its author triggers 101 database queries. Eager loading (using Include in EF Core, or JOINs directly) collapses this into 1-2 queries. Understanding ORM behavior is critical for full-stack performance.",
                    skillId: 43),
                CreateQuestion(id++, "You are building a full-stack feature that requires both the frontend and backend to be developed simultaneously by the same developer. How do you avoid blocking yourself?",
                    QuestionCategory.Technical, JobTitleRoleFamily.FullStack,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "Always build the backend completely before writing any frontend code.", "Design and agree on the API contract (endpoints, request/response shape) first, then mock the backend responses in the frontend while building the real backend in parallel.", "Build the frontend first and design the API based on whatever data the UI happens to need.", "Use the same codebase for both frontend and backend to avoid synchronization issues." },
                    1, "API-first design is the key to parallel development. By defining the contract (often as an OpenAPI spec or just a shared document) before writing code, the frontend developer can mock responses and work independently. Without this, full-stack developers often waste time waiting on themselves. Tools like MSW (Mock Service Worker) make frontend mocking production-quality.",
                    skillId: 43),
                CreateQuestion(id++, "What is the key difference between authentication and authorization in a full-stack application, and where should each be enforced?",
                    QuestionCategory.Technical, JobTitleRoleFamily.FullStack,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "Authentication is only needed for admin panels; regular users do not need to be authenticated.", "They are synonymous — both mean verifying that a user is logged in.", "Authentication is enforced on the frontend and authorization on the backend.", "Authentication (who are you?) verifies identity, typically via JWT or session; authorization (what can you do?) checks permissions. Both must be enforced on the server, never solely on the client." },
                    3, "Enforcing authorization only on the frontend is a critical security flaw — anyone can bypass it. Authentication verifies who you are (login), authorization verifies what you can access (role checks). Both must be re-validated on every API request, since the client cannot be trusted. Full-stack developers must implement middleware to guard backend routes.",
                    skillId: 43),
                CreateQuestion(id++, "In a full-stack application, what is the purpose of a reverse proxy (e.g., Nginx, Caddy) in a production deployment?",
                    QuestionCategory.Technical, JobTitleRoleFamily.FullStack,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "A reverse proxy sits in front of the application servers, handling SSL termination, load balancing, static file serving, and routing requests to the appropriate backend service.", "A reverse proxy replaces the database and caches all SQL queries in memory.", "A reverse proxy is a security tool that blocks all incoming HTTP requests by default.", "A reverse proxy converts backend API responses from JSON to XML for legacy client compatibility." },
                    0, "Full-stack developers deploying to production must understand the infrastructure layer. Nginx (or similar) handles HTTPS, routes /api requests to the backend and / requests to the frontend, and serves static assets from disk rather than the application server. This architectural pattern is industry-standard and dramatically improves security and performance.",
                    skillId: 43),
                CreateQuestion(id++, "What is optimistic UI updating in a full-stack context, and what is the risk?",
                    QuestionCategory.Technical, JobTitleRoleFamily.FullStack,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "Optimistic UI refers to caching server responses to avoid future API calls.", "Optimistic UI is a CSS animation technique to make page transitions feel faster.", "Optimistic UI updates the interface immediately assuming the API call will succeed, then reverts on failure. The risk is a mismatch between UI state and server state if the request fails.", "Optimistic UI always waits for the server response before updating the interface." },
                    2, "Optimistic updates (used in tools like React Query and Apollo) provide instant-feeling UI responses, greatly improving perceived performance. However, if the server rejects the request (validation error, network failure), the UI must roll back to the previous state. Handling failure cases correctly is the hard part that distinguishes senior full-stack developers.",
                    skillId: 43),
                CreateQuestion(id++, "What is the difference between horizontal and vertical scaling in a full-stack backend, and what architectural decisions enable horizontal scaling?",
                    QuestionCategory.Technical, JobTitleRoleFamily.FullStack,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "Vertical scaling adds more resources to one server; horizontal scaling adds more servers. Stateless APIs, external session storage, and distributed caching (Redis) enable horizontal scaling.", "Both scaling strategies require the same architectural changes.", "Horizontal scaling only applies to databases, not application servers.", "Horizontal scaling means upgrading the CPU; vertical scaling means adding more servers." },
                    0, "Vertical scaling (bigger server) has limits and is expensive. Horizontal scaling (more servers) is theoretically unlimited but requires the application to be stateless, since a request can hit any server. This means sessions must be externalized (Redis), file uploads must go to object storage (S3), and application logic must be idempotent — all key full-stack architectural concerns.",
                    skillId: 43),
                CreateQuestion(id++, "In a full-stack application, what is the purpose of input sanitization versus input validation, and why do you need both?",
                    QuestionCategory.Technical, JobTitleRoleFamily.FullStack,
                    QuestionDifficulty.Medium, ExperienceSeniorityLevel.Mid,
                    new[] { "Sanitization is only necessary for user-facing display; API endpoints do not need it.", "Validation checks if input meets rules (e.g., email format); sanitization transforms input to remove dangerous content (e.g., HTML tags). You need both to ensure correctness and prevent injection attacks.", "They are synonymous — both refer to checking that input is in the correct format.", "Validation is done on the frontend and sanitization is done on the backend." },
                    1, "Validation rejects invalid inputs before they reach the system. Sanitization transforms potentially dangerous inputs into safe equivalents (stripping script tags, escaping SQL characters). Using validation alone without sanitization can miss subtle attack vectors. Using sanitization alone without validation can produce nonsensical but safe data. Both layers working together provide defense in depth.",
                    skillId: 43),
                CreateQuestion(id++, "You are architecting a full-stack feature where the same data is read by thousands of concurrent users but updated infrequently. What architectural pattern maximizes performance?",
                    QuestionCategory.Technical, JobTitleRoleFamily.FullStack,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "Add a database read replica and route all reads to it.", "Implement a caching layer (Redis or CDN edge cache) in front of the API, serve cached responses for reads, and invalidate the cache only on writes.", "Increase the database connection pool size to handle concurrent reads.", "Shard the database horizontally so each user hits a different database instance." },
                    1, "Read-heavy workloads are the ideal use case for caching. A cache-aside pattern (check cache first, fall back to DB, populate cache on miss) with targeted cache invalidation on writes dramatically reduces database load. Read replicas also help but add replication lag. Sharding solves a different problem (write throughput). Caching is the first-line solution for read-heavy systems.",
                    skillId: 43),
                CreateQuestion(id++, "What is an idempotent API operation, and why is idempotency critical for full-stack reliability?",
                    QuestionCategory.Technical, JobTitleRoleFamily.FullStack,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "An idempotent operation can only be called once before requiring a new authentication token.", "Idempotency means the API response is always identical for all users.", "An idempotent operation produces the same result regardless of how many times it is called with the same inputs. This ensures that network retries and duplicate requests do not cause unintended side effects like double-charging.", "An idempotent operation is one that never fails under any circumstances." },
                    2, "In distributed systems, network failures happen. A client that times out does not know if the server processed the request. If the operation is not idempotent (like charging a card), a retry causes a double charge. Building idempotent APIs using idempotency keys (a unique request ID the client generates) allows safe retries. This is a key design principle for payment systems and critical operations.",
                    skillId: 43),
                CreateQuestion(id++, "In a full-stack application, what is database connection pooling and why does its misconfiguration cause hard-to-diagnose production failures?",
                    QuestionCategory.Technical, JobTitleRoleFamily.FullStack,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "Connection pooling only applies to NoSQL databases and is irrelevant for SQL databases.", "Connection pooling reuses existing database connections instead of creating new ones per request. Too small a pool causes request timeouts under load; too large a pool can exhaust database connection limits and cause crashes.", "Connection pooling is an automatic feature managed entirely by the database and requires no developer configuration.", "Connection pooling refers to running multiple database servers in parallel to distribute queries." },
                    1, "Database connections are expensive to create and limited in number. Connection pools maintain a set of reusable connections. Under load, if all connections are in use, new requests queue or timeout. If the pool is too large, the database server runs out of connections across all application instances. Tuning pool size based on load testing is a critical production configuration task for full-stack developers.",
                    skillId: 43),
                CreateQuestion(id++, "You need to implement a full-stack feature that sends thousands of emails after a user action. Why is it wrong to do this synchronously in the API handler, and what is the correct architecture?",
                    QuestionCategory.Technical, JobTitleRoleFamily.FullStack,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "Synchronous processing blocks the API response until all emails are sent (potentially minutes), causing timeouts. The correct approach is to push the work to a message queue (RabbitMQ, Redis, SQS) and process it asynchronously with background workers.", "It is fine to process emails synchronously as long as you increase the API timeout to 10 minutes.", "Synchronous email sending is acceptable because SMTP servers always respond within milliseconds.", "Emails should always be sent directly from the frontend to avoid burdening the backend." },
                    0, "Long-running operations in API handlers are a reliability anti-pattern. If the API times out, the client cannot tell if the work completed. Message queues decouple the trigger from the work: the API enqueues the job instantly (milliseconds) and returns, then background workers process it reliably with automatic retries on failure. This is the foundation of all modern async full-stack architectures.",
                    skillId: 43),
                CreateQuestion(id++, "What is the difference between optimistic and pessimistic concurrency control in a full-stack backend, and when would you use each?",
                    QuestionCategory.Technical, JobTitleRoleFamily.FullStack,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "Pessimistic locking blocks other transactions from reading or writing a record while it is being updated, preventing conflicts but reducing throughput. Optimistic locking allows concurrent reads, checks for conflicts at commit time, and rejects if the record changed. Use pessimistic for high-contention critical sections, optimistic for low-contention scenarios.", "Pessimistic control is always better because it guarantees no data conflicts ever occur.", "Optimistic locking is only available in NoSQL databases.", "They are the same mechanism with different naming conventions." },
                    0, "Concurrency control prevents lost updates when multiple users edit the same record simultaneously. Pessimistic locks (SELECT FOR UPDATE) are safe but create bottlenecks under high concurrency. Optimistic locks (row version or timestamp columns) scale better because they do not hold locks, but require the application to handle conflict resolution. Full-stack developers choose based on contention probability and business tolerance for retry loops.",
                    skillId: 43),
                CreateQuestion(id++, "How would you design a full-stack feature for exporting a very large dataset (millions of rows) to CSV without causing timeouts or memory exhaustion?",
                    QuestionCategory.Technical, JobTitleRoleFamily.FullStack,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "Stream the data from the database query directly to the HTTP response using a chunked transfer, or generate the file asynchronously in a background job and provide a download link when complete.", "Increase the server RAM to accommodate the full dataset in memory.", "Load all rows into server memory as a list, serialize to CSV, and return it as a single response.", "Use pagination and have the frontend make thousands of API calls to download the data in pages." },
                    0, "Loading millions of rows into memory causes out-of-memory crashes. Streaming uses database cursors to read and write one chunk at a time, keeping memory usage constant regardless of dataset size. The async background job approach is better for very slow exports — it prevents HTTP gateway timeouts and lets the user do other things while waiting. Both are valid full-stack architectural patterns.",
                    skillId: 43),
                CreateQuestion(id++, "What is a distributed transaction problem in a full-stack microservices context, and what pattern is commonly used to solve it?",
                    QuestionCategory.Technical, JobTitleRoleFamily.FullStack,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "When an operation spans multiple services (e.g., charging a payment service and updating an inventory service), a failure in one service after the other succeeds leaves data inconsistent. The Saga pattern solves this with a sequence of local transactions and compensating rollback transactions.", "The problem is solved by ensuring all services are always available using 99.99% uptime SLAs.", "Distributed transactions are solved by using a single shared database across all microservices.", "Distributed transactions only occur in systems with more than 100 servers." },
                    0, "Traditional ACID transactions do not span service boundaries. The Saga pattern breaks a distributed transaction into a series of local transactions. If any step fails, compensating transactions (refunds, rollbacks) are executed to undo completed steps. This is a fundamental pattern in microservices architecture that every senior full-stack developer working at scale must understand.",
                    skillId: 43),
                CreateQuestion(id++, "In a full-stack system under heavy load, you notice the database becomes the bottleneck even with indexes in place. What sequence of escalating optimizations would you apply?",
                    QuestionCategory.Technical, JobTitleRoleFamily.FullStack,
                    QuestionDifficulty.Hard, ExperienceSeniorityLevel.Senior,
                    new[] { "Immediately scale vertically by buying a larger database server.", "Disable all database constraints and indexes to maximize write throughput.", "First: optimize queries and add missing indexes. Second: implement application-level caching (Redis). Third: add read replicas for read scaling. Fourth: consider database sharding or moving hot data to a specialized store.", "Migrate all data to a NoSQL database immediately." },
                    2, "Database optimization follows a cost-benefit escalation. Query optimization and indexes are free and often solve most issues. Caching eliminates entire classes of read queries. Read replicas distribute read load. Sharding is expensive and complex and should only be used when simpler approaches are exhausted. This disciplined escalation prevents over-engineering.",
                    skillId: 43),
            });

            return questions;
        }

        private static AssessmentQuestion CreateQuestion(
            int id,
            string questionText,
            QuestionCategory category,
            JobTitleRoleFamily roleFamily,
            QuestionDifficulty difficulty,
            ExperienceSeniorityLevel seniorityLevel,
            string[] options,
            int correctAnswerIndex,
            string explanation,
            int skillId = 0)
        {
            return new AssessmentQuestion
            {
                Id = id,
                QuestionText = questionText,
                Category = category,
                RoleFamily = roleFamily,
                SkillId = skillId,
                Difficulty = difficulty,
                SeniorityLevel = seniorityLevel,
                Options = System.Text.Json.JsonSerializer.Serialize(options),
                CorrectAnswerIndex = correctAnswerIndex,
                TimePerQuestion = 60,
                IsActive = true,
                CreatedAt = SeedCreatedAt,
                UpdatedAt = SeedCreatedAt,
                Explanation = explanation
            };
        }
    }
